  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('e4e94bad-11a7-5c01-90f5-240b078694cf', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical and precise word or phrase?', '["share", "split", "challenge", "examine"]'::jsonb, 1, 'Becoming a member of the organization Indigenous Photograph has helped Sara Aliaga Ticona (Aymara) to _____ her work with an audience beyond Bolivia, where she’s from. The organization’s database of members is used by photography editors and others in the media industry around the world.'),
  ('ae3902db-c68e-53fb-b290-2672b25c17cb', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical and precise word or phrase?', '["straightening", "relying on", "reducing", "forgetting about"]'::jsonb, 2, 'Since the Hubble Space Telescope was launched into space in 1990, astronauts have needed to complete regular missions to repair the telescope and keep it working smoothly. Researchers hope that robots will soon be able to make these repairs. Employing robots instead of humans to make repairs will be helpful, as _____ astronauts to maintain the telescope can be expensive.'),
  ('6bb81de9-3eef-563c-8376-34803291ab01', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical and precise word or phrase?', '["controversy", "sincerity", "esteem", "thoughtfulness"]'::jsonb, 3, 'In 1776, the United States sent Benjamin Franklin to France to try to win the country’s support in the United States'' fight for independence from Great Britain. Franklin was very popular in France. This _____ surely helped him to convince France to assist the United States.'),
  ('a2e4b405-2afa-59da-896a-09c7b6e1c1ea', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical and precise word or phrase?', '["a haphazard", "a contentious", "an ineffectual", "an arduous"]'::jsonb, 4, 'The creation of Lotte Reiniger’s 1926 animated film The Adventures of Prince Achmed was _____ process. Over the course of three years, Reiniger and her collaborators painstakingly made more than 250,000 individual images of hand-cut paper silhouettes and repeatedly had to invent entirely new methods and tools to create the special effects Reiniger envisioned.'),
  ('7e475e2a-b8f5-5be1-8979-b9782bb2c649', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice best describes the function of the reference to Brown’s biography in the text as a whole?', '["It emphasizes that Brown’s life has been a popular subject for writers because it was so remarkable.", "It suggests that other people who are familiar with Brown’s life would share the author’s view of her.", "It explains why Brown was unique amongst her peers.", "It describes the nature of the relationship between Yung and Brown."]'::jsonb, 5, 'The following text is from Yung Wing’s 1909 memoir My Life in China and America. Yung Wing was the first American college graduate of Chinese heritage; Phoebe Brown was the first prominent female hymn writer in the United States.
I look back upon my acquaintance with Mrs. Phoebe H. Brown with a mingled feeling of respect and admiration. She certainly was a remarkable New England woman—a woman of surpassing strength of moral and religious character. <u>Those who have had the rare privilege of reading her stirring</u> <u>biography, will, I am sure, bear me out in this statement.</u> She went through the crucible of unprecedented adversities and trials of life and came out one of the rare shining lights that beautify the New England sky.'),
  ('095b746a-31c0-56ff-8e1d-6d9670a0aebc', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It explains what can be gained from a scientific approach to understanding natural phenomena.", "It describes an intensely debated scientific controversy that Victor dedicated his life to resolving.", "It undermines the idea that a practical approach to understanding natural phenomena is inferior to a scientific approach.", "It suggests that Victor did not discover what he wanted to know from the scientific research available to him."]'::jsonb, 6, 'The following text is from Mary Shelley’s 1818 novel Frankenstein. Victor Frankenstein, who is narrating this portion of text, describes the state of scientific knowledge as he began his own study of the natural world.

The untaught peasant beheld the elements around him and was acquainted with their practical uses. The most learned philosopher knew little more. He had partially unveiled the face of Nature, but her immortal lineaments were still a wonder and a mystery. <u>He might dissect, anatomise, and give</u> <u>names, but, not to speak of a final cause, causes in their secondary and tertiary grades were utterly</u> <u>unknown to him</u>. I had gazed upon the fortifications and impediments that seemed to keep human beings from entering the citadel of nature, and rashly and ignorantly I had repined.'),
  ('d0605f98-a150-5d73-a146-c2af7599fd24', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice best states the main idea of the text?', '["The National Association of Black Journalists was founded in Washington, DC, in the 1900s.", "Black journalists has an interesting history both inside and outside the United States.", "Cunningham’s achievements are often overlooked in countries other than the United States.", "Black journalism in the United States has an important history that the National Association of Black Journalists helps to honor."]'::jsonb, 7, 'In the 1940s, Evelyn Cunningham worked for the Pittsburgh Courier, focusing on coverage of the early civil rights movement. Cunningham’s accomplishment is just one example of the rich history of Black journalism in the United States. That history is preserved by the National Association of Black Journalists, which was founded in Washington, D.C. in 1975 to support Black media professionals and honor people like Cunningham.'),
  ('644d9a42-917b-5af1-86cf-f5d5f5030de0', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice best states the main idea of the text?', '["Both ocelots and jaguars have U-shaped hyoid bones, but ocelots hyoids are rigid whereas jaguars'' hyoids are flexible.", "Researchers are uncertain why relatively small cats, such as ocelots, purr but relatively large cats, such as jaguars, roar.", "Jaguars and most other species of big cats can roar because they have flexible hyoid bones that are attached by stretchy ligaments to their skulls.", "Differences related to the hyoid bone in ocelots and jaguars may help explain why one species purrs and the other roars."]'::jsonb, 8, 'Why do ocelots purr but jaguars roar? Researchers hypothesize that this difference between the two feline species may be partly due to a U-shaped bone in their throats called the hyoid. Ocelots, which are much smaller than jaguars, have a rigid hyoid that rumbles when the cat’s larynx vibrates, resulting in a purr. By contrast, jaguars have a somewhat flexible hyoid, and the bone is attached to the skull with a stretchy ligament that ocelots lack. These traits allow jaguars and most other species of big cats to produce powerful roars. The same traits may also prevent most big cats from purring.'),
  ('c0462a7b-1662-5162-9bf4-caa9bdce14f2', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice best states the main idea of the text?', '["The English words “coyote” and “condor” are both examples of loanwords from Indigenous languages.", "When borrowing from Indigenous languages, Spanish adopted roughly as many words from Nahuatl as from Quechua.", "Many Spanish words with Indigenous origins first passed through English before entering Spanish.", "When non-Indigenous languages borrowed from Indigenous languages, the words often underwent a significant change in meaning."]'::jsonb, 9, '"Coyote" is an example of a loanwordthat is, a word that originated in one language and was later adopted by another. The word came to English indirectly from coyote, the Spanish word for the wild canine species. Spanish had borrowed it from Nahuatl, an Indigenous language of Central Mexico, in which the word’s original form is coyotl. "Condor" also has an Indigenous origin and entered English through Spanish, but in this case, the original source was Quechua, a language of South America, in which the word for the large vulture species is kuntur.'),
  ('8c5cbd94-74e0-5486-859d-10d2fc3dad95', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which finding, if true, would most directly support Bainbridge and colleagues'' claim?', '["The heart rates of infants in the study were more irregular during the lullabies than during non-lullabies.", "Infants'' heart rates were substantially lower during the lullaby than during the non-lullaby.", "Parents of infants in the study chose the lullaby over the non-lullaby when asked which song they would use to calm their child.", "Both the song in Luk Saami and the song in Tundra Nenets were sung by a female singer."]'::jsonb, 10, 'Many believe that lullabies, characterized by their slow tempos, contain some acoustic features that are universally calming to infants. In a study, Constance M. Bainbridge and colleagues played both a lullaby sung in the Luk Saami language and a non-lullaby sung in the Tundra Nenets language to a group of infants. The researchers also measured the infants’ heart rates, as a reduced heart rate is considered a measure of relaxation. They claim that the lullaby did indeed relax the infants.'),
  ('f899c6da-44cc-59b9-a682-cdfc8c1d0513', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which quotation from A Pair of Silk Stockings most effectively illustrates the claim?', '["\"She handed the girl a five-dollar bill and waited for her change and for her parcel. What a very small parcel it was!\"", "\"She had no time, no second of time to devote to the past. The needs of the present absorbed her every faculty.\"", "\"She was not thinking at all. She seemed for the time to be taking a rest from that laborious and fatiguing function and to have abandoned herself to some mechanical impulse that directed her actions and freed her of responsibility.\"", "\"Mrs. Sommers selected a black pair and looked at them very long and closely. She pretended to be examining their texture, which the clerk assured her was excellent.\""]'::jsonb, 11, 'A Pair of Silk Stockings is an 1897 short story by Kate Chopin. In the story, Mrs. Sommers is depicted as sometimes making decisions without conscious deliberation: ______'),
  ('a8d38c49-3475-52b9-b702-5a3d8a7a5d3d', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which quotation from a psychologist not involved in the team’s study would most directly weaken the team’s conclusion?', '["“When an individual chooses to produce volitional laughter in a natural social context, the laughter often shares certain acoustic qualities, such as pitch and fluctuation of intensity, with spontaneous laughter.”", "“Although the team considered the average size of communities in each society in the study, that demographic factor was found to have no effect on listeners'' identifications of laughter as spontaneous or volitional.”", "“Judgments of spontaneous laughter are often associated with acoustic features such as greater intensity variability and higher pitch.”", "“Recent studies in communications have shown that certain acoustic features of spontaneous laughter, such as pitch and intensity, are consistent both within and across societies.”"]'::jsonb, 12, 'Psychologists Gregory Bryant, Dorsa Amir, and colleagues investigated cross-cultural perceptions of spontaneous (real) laughter and volitional (fake or forced) laughter. Study participants from 21 societies, including those in Austria and Turkey, listened to randomized recordings of 18 spontaneous laughs taken from natural conversations between pairs of women and 18 volitional laughs produced separately by 18 different women in response to an experimenter’s instruction to laugh. Analysis of the participants'' evaluations of the laughs prompted the team to conclude that the ability to distinguish between spontaneous and volitional laughter appears to be universal across cultures.'),
  ('f4f265b9-a760-5d9d-96e5-9e990e79cc9a', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice most effectively uses data from the graph to complete the assertion?', '["increase in the forest cover area for all classes from 1979 to 2000.", "similarity in forest cover area in Class I-IV and Class VII in 1986.", "difference between the forest cover area in Class I-IV and in Class VI in 2000.", "decrease in the forest cover area for all classes from 1960 to 1979."]'::jsonb, 13, '![figure](/q/aug24/001.webp)

To understand the extent of deforestation in the Chorotega region of Costa Rica, Juan Pablo Arroyo-Mora and colleagues used historical aerial photography and remote sensing data to track changes in the forest cover area across different land use capability classes (categories that indicate possible uses of forest land). Due to the Chorotega region’s climate, various types of forested areas were converted to cattle pasture as rising international meat prices drove a cattle ranching boom in the 1960s and 1970s. By the mid-1980s, however, increased public awareness and environmental reforms, along with a decline in meat prices, triggered a natural regrowth process, as evident by the _____'),
  ('3a880c37-3c8f-5464-9b85-ce7acc31bae0', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice most logically completes the text?', '["M. knippeliana may have been overlooked in eastern and western Coahuila because of its similarity to another species.", "the current methods of collecting and tracking Mammillaria species throughout Mexico may cause an overestimation of the number of species in this genus.", "the perceived absence of Mammillaria in eastern and western Coahuila may be due to insufficient exploration of the region.", "the dense vegetation and high annual precipitation levels in eastern and western Coahuila impede the ability of Mammillaria species to survive."]'::jsonb, 14, 'There are over 150 species of the cactus genus Mammillaria throughout the Americas, but their survival can be threatened by high precipitation and dense vegetation that blocks sunlight. Researchers have located species from the genus in almost every state in Mexico, with several of them, like M. knippeliana, restricted to only one state. The fact that this genus has not been observed in eastern and western Coahuila has been attributed to a lack of appropriate habitat, but much of the landscape in this area is notoriously inaccessible, which suggests that _______'),
  ('b6dfdb9c-45b4-56fe-80d0-a2ee91c4be7c', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["having contained", "to contain", "containing", "contains"]'::jsonb, 15, 'The 1958 poem "The Ghost’s Leavetaking" by American author Sylvia Plath __ the first use of the word "dreamscape."'),
  ('587f1617-d622-52dc-af4f-a1aefc7b5cb2', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were entering", "enter", "has entered", "have entered"]'::jsonb, 16, 'Florence Esté and Lily Everett were among the 300 artists who exhibited at the 1913 Armory Show, a groundbreaking New York City art exhibition that introduced modernism to American audiences. Though shocking at the time, an abstract cubist painting exhibited by Marcel Duchamp—one of several works that received scorn from critics—________ the Western art canon more than a century later.'),
  ('48e98338-1260-5392-bb8a-034a15852e07', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["vapor. With", "vapor and with", "vapor, with", "vapor with"]'::jsonb, 17, 'Increasing the heat on an uncovered boiling pot of water does not increase the temperature of the water. What increases is the rate at which the water turns to _____ a pressure cooker pot, though, an airtight seal traps the vapor in the pot, creating pressure that allows the temperature of the water to increase past its boiling point.'),
  ('2c2a50c4-82c1-5312-8d68-fb5ac64477dc', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["direction\"", "direction\" and,", "direction\";", "direction,\""]'::jsonb, 18, 'Each year, a Nobel Prize in Literature is given to an author who has, in the words of its founder Alfred Nobel, "produced the most outstanding work in an idealistic _____ in 1912, for instance, judges recognized Gerhart Johann Robert Hauptmann "[for] his fruitful, varied and outstanding production in the realm of dramatic art.”'),
  ('34b48f5b-c602-5294-a28a-c05664408532', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["windows; transitional", "windows. Transitional", "windows—transitional", "windows, transitional"]'::jsonb, 19, 'With a blend of traditional design elements, such as arched Gothic ceilings, and modern ones, such as floor-to-ceiling _____ design splits the difference between old and new, a mixture that is increasingly seen in home interiors in the US.'),
  ('6f0ca144-8b5b-5c8f-b7f6-c0f3e0c7d789', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["artists Thomas Hart Benton, and Jackson Pollack,", "artists: Thomas Hart Benton and Jackson Pollack,", "artists Thomas Hart Benton and Jackson Pollack", "artists, Thomas Hart Benton and Jackson Pollack"]'::jsonb, 20, 'Paintings by the renowned twentieth-century US _____ were featured in Artist to Artist, an exhibition at the Smithsonian Art Museum that paired the works of artists whose career trajectories intersected in meaningful ways.'),
  ('3e2ffc8e-026e-522c-97eb-44dd1a12f55c', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical transition?', '["In any case,", "Finally,", "For instance,", "In doing so,"]'::jsonb, 21, 'In March 1862, John Ahoy joined the US Navy, where he went on to serve aboard the USS Pinola during the US Civil War. _____ he earned a place in US history as one of the war’s few Chinese-born American soldiers.'),
  ('c3e32d91-c747-52e4-b3ae-f2d8a8ba3ca2', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical transition?', '["As a result,", "That is,", "By comparison,", "For instance,"]'::jsonb, 22, 'The London Array, an offshore wind farm located off the coast of England, produces about 630 megawatts (MW) of electricity per year. ________ England’s Hornsea Project One offshore wind farm, which generates the most power of any single offshore farm, produces 1,218 MW of electricity.'),
  ('fb7382fd-20db-55f0-a3e5-671a584e2ef0', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical transition?', '["Specifically,", "Regardless,", "Earlier,", "However,"]'::jsonb, 23, 'In 1974, Mexican chemist Mario Molina and US chemist F. Sherwood Rowland discovered that chemicals called CFCs were harmful to the ozone layer. Their research was extremely influential in the fight against CFCs. _____ it laid the foundation for a 1987 treaty that phased out the use of CFCs across the globe.'),
  ('e4f2795c-c9ab-59e0-aa08-a6f6b0983664', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice completes the text with the most logical transition?', '["for example", "additionally", "meanwhile", "however"]'::jsonb, 24, 'Generally, sleek vehicles are more aerodynamic than bulkier ones. The streamlined nose of the Airbus A320 jet, ________, helps it glide through wind with relative ease, while a boxy pickup truck encounters more wind resistance, making it less aerodynamic.'),
  ('bad11dfc-3e21-5fe0-b22e-70e66b518723', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'Which choice most effectively uses information from the given sentences to present the study and its findings?', '["In Puerto Rico, the genus Hemisotoma contains one springtail species, and the genus Sphaeridia.", "According to a study by researchers Claudia Marcela Ospina-Sánchez, Felipe N. Soto-Adames, and Grizelle González, there are 146 springtail species present in Puerto Rico, including one from the genus Hemisotoma and three from the genus Sphaeridia.", "Researchers Claudia Marcela Ospina-Sánchez, Felipe N. Soto-Adames,and Grizelle González studied springtails in Puerto Rico, and they wanted to know how many species there are in the genus Hemisotoma and the genus Sphaeridia.", "There are 146 species of springtail (noninsect hexapods) in Puerto Rico, but there are more species from the genus Sphaeridia than from the genus Hemisotoma."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Springtails are a group of noninsect hexapods (six-legged animals).
Researchers Claudia Marcela Ospina-Sánchez, Felipe N. Soto-Adames, and Grizelle González conducted a study to determine how many springtail species are present in Puerto Rico. They found a total of 146 springtail species.
They found 1 springtail species belonging to the genus Hemisotoma.
They found 3 springtail species belonging to the genus Sphaeridia.'),
  ('78d8a874-cd28-5c63-a20d-654d7d6f3304', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'The student wants to explain what a merchant vessel is and provide examples. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["There were a total of 1,236 ships hired to carry cargo or passengers registered in Greece in 2021.", "The carrying capacity of bulk carriers, cruise liners, and oil tankers is measured in deadweight tonnage.", "A merchant vessel is any ship hired to carry cargo or passengers like bulk carriers, cruise liners, and oil tankers.", "In total, Greece’s 1,236 merchant vessels had a carrying capacity of 64.9 million tons in 2021."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

A merchant vessel is any ship hired to carry cargo or passengers. Common merchant vessels include bulk carriers, cruise liners, and oil tankers.
A vessel’s carrying capacity is also known as its deadweight tonnage (DWT).
In 2021, there were a total of 1,236 merchant vessels registered in Greece.
The combined DWT of these vessels was 64.9 million tons.'),
  ('2fd75b64-c9b1-5dd6-b6db-6c54aa0f23bd', 'f176b4c5-1bef-5a56-97b9-5404e3a48197', 'The student wants to contrast the song Poor Miner’s Farewell with the song Bring Him Back Home. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["While both are protest songs, Poor Miner’s Farewell is about coal miners in Kentucky, whereas Bring Him Back Home is about the anti-apartheid leader Nelson Mandela.", "Hugh Masekala’s song Bring Him Back Home, released in 1987, called on the South African government to free Nelson Mandela.", "The songs Poor Miner’s Farewell and Bring Him Back Home both raised awareness about human rights violations.", "Released in 1932 by Aunt Molly Jackson, the song Poor Miner’s Farewell was a protest against the unlivable wages and dangerous working conditions faced by Kentucky coal miners."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Musicians around the world have used protest songs to raise awareness about human rights violations.
US folk singer Aunt Molly Jackson released the protest song Poor Miner27s Farewell in 1932. It exposed the unlivable wages and dangerous working conditions coal miners faced in Kentucky during the 1920s and 1930s.
South African singer-songwriter Hugh Masekela released the protest song Bring Him Back Home in 1987.
It called on the South African government to free Nelson Mandela, an anti-apartheid leader who''d been unjustly imprisoned.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('e4e94bad-11a7-5c01-90f5-240b078694cf', 0, null, '**Choice A is correct.** The sentence describes how membership in an organization helped Sara Aliaga Ticona reach people beyond her home country; "share" precisely conveys making her photographic work available to an audience outside Bolivia, which matches the following clause explaining the organization’s database is used by editors and media professionals worldwide.
**Choice B is incorrect.** "Split" means to divide into parts, which does not fit the idea of distributing or making work available to a broader audience.
**Choice C is incorrect.** "Challenge" would mean to question or dispute her work, which conflicts with the supportive context about exposure provided by the organization’s database.
**Choice D is incorrect.** "Examine" means to study or inspect, which does not match the notion of reaching or presenting work to an audience.
**Faster approach:** Substitute each choice into the sentence and choose the one that preserves the intended meaning of gaining exposure—this quickly eliminates words that imply division, scrutiny, or dispute.'),
  ('ae3902db-c68e-53fb-b290-2672b25c17cb', 1, null, '**Choice B is correct.** The sentence needs a verb phrase that describes what makes using humans costly; "relying on astronauts to maintain the telescope can be expensive" clearly and precisely expresses that depending on human missions is costly. The gerund phrase "relying on astronauts" fits the grammar and the intended meaning.
**Choice A is incorrect.** "Straightening astronauts to maintain the telescope" is meaningless in context; "straightening" does not relate to assigning or depending on personnel.
**Choice C is incorrect.** "Reducing astronauts to maintain the telescope" is ungrammatical or illogical here: it suggests making astronauts smaller or fewer, and does not convey the intended costliness of depending on them.
**Choice D is incorrect.** "Forgetting about astronauts to maintain the telescope" conflicts with the idea of replacing them with robots and is awkward; it doesn’t explain why employing robots is helpful because of expense.
**Faster approach:** Plug each choice into the sentence and choose the one that yields a grammatical, sensible meaning—this quickly eliminates implausible verbs.'),
  ('6bb81de9-3eef-563c-8376-34803291ab01', 2, null, '**Choice C is correct.** The sentence says Franklin "was very popular in France," and the blank refers back to that popularity as a factor that helped him convince France to assist the United States. "Esteem" is a noun meaning respect or admiration, which directly restates the idea of being popular and fits logically and grammatically: "This esteem surely helped him..."
**Choice A is incorrect.** "Controversy" means disagreement or dispute, which contradicts the claim that Franklin was popular and would not logically explain why France would be persuaded to assist.
**Choice B is incorrect.** "Sincerity" could plausibly help persuasion, but the sentence points to Franklin’s popularity specifically; "sincerity" introduces a new trait not mentioned and is less precise.
**Choice D is incorrect.** "Thoughtfulness" denotes careful consideration and does not directly restate popularity or explain why the French admired or trusted Franklin, so it is not as logically precise as "esteem."
**Faster approach:** Look for a word that restates or directly follows the immediately preceding idea (popularity → esteem); choose the synonym that matches part of speech and meaning.'),
  ('a2e4b405-2afa-59da-896a-09c7b6e1c1ea', 3, null, '**Choice D is correct.** The surrounding details—“over the course of three years,” “painstakingly made more than 250,000 individual images,” and repeatedly inventing new methods—emphasize sustained effort and difficulty; the adjective “arduous” precisely conveys a long, difficult, labor-intensive process.
**Choice A is incorrect.** “A haphazard” means random or lacking organization, which contradicts the passage’s emphasis on painstaking, methodical labor and invention of techniques.
**Choice B is incorrect.** “A contentious” means causing or involving disagreement or controversy; nothing in the passage suggests dispute or controversy about the film’s creation.
**Choice C is incorrect.** “An ineffectual” means not producing the desired effect; the passage instead highlights productive, innovative effort, so this meaning is inconsistent with the context.
**Faster approach:** Spot strong context clues (time span, quantity, “painstakingly”) that signal difficulty or effort—choose a synonym like “arduous.”'),
  ('7e475e2a-b8f5-5be1-8979-b9782bb2c649', 1, null, '**Choice B is correct.** The sentence appeals to readers who have "had the rare privilege of reading her stirring biography" and says they "will, I am sure, bear me out in this statement," which explicitly invites agreement from others familiar with Brown’s life. Thus the reference functions to suggest that other informed people would share the author’s positive view.
**Choice A is incorrect.** The sentence does not claim widespread popularity or that many writers treated her life as a subject; it only refers to those who have read the biography and would confirm the author’s opinion.
**Choice C is incorrect.** The clause does not explain why Brown was unique; it appeals to corroboration rather than giving reasons for her uniqueness.
**Choice D is incorrect.** The sentence does not describe the personal relationship between Yung and Brown; it comments on readers of her biography and their likely agreement with the author.
**Faster approach:** Look for explicit signal verbs ("bear me out," "agree") that show the clause’s function—if it asks others to confirm the claim, choose the answer about shared opinion or corroboration.'),
  ('095b746a-31c0-56ff-8e1d-6d9670a0aebc', 3, null, '**Choice D is correct.** The underlined sentence emphasizes the limits of learned philosophers'' scientific knowledge: they could dissect and name things but lacked understanding of final and deeper causes. In the context of Victor’s narration about the insufficiency of contemporary science, this line supports the idea that the available scientific research did not provide the ultimate answers Victor sought.
**Choice A is incorrect.** The sentence does not highlight benefits of the scientific approach; it stresses what science fails to explain rather than what it gains.
**Choice B is incorrect.** The sentence does not present a particular debated controversy or a specific problem Victor set out to resolve; it makes a general claim about limits of knowledge.
**Choice C is incorrect.** The sentence does not defend the practical knowledge of peasants or argue that practical approaches are superior; instead it points out shortcomings in learned (scientific) understanding.
**Faster approach:** Focus on the key negative words (e.g., "utterly unknown") to determine whether the sentence emphasizes limits or strengths; that immediately narrows choices to ones about insufficiency versus benefit.'),
  ('d0605f98-a150-5d73-a146-c2af7599fd24', 3, null, '**Choice D is correct.** The passage states that Cunningham’s work is “one example of the rich history of Black journalism in the United States,” and that the National Association of Black Journalists “was founded in Washington, D.C. in 1975 to support Black media professionals and honor people like Cunningham,” which directly supports the idea that Black journalism has an important U.S. history that the association helps honor.
**Choice A is incorrect.** The passage gives the founding year as 1975, not merely “the 1900s,” and specifies the purpose of the organization rather than only its founding date.
**Choice B is incorrect.** The passage discusses Black journalism’s history in the United States only; it does not claim an interesting history “both inside and outside the United States.”
**Choice C is incorrect.** The passage does not say Cunningham’s achievements are overlooked in other countries; it focuses on honoring her within the U.S. context.
**Faster approach:** Read the topic sentence(s) and concluding sentence of the passage to identify the author’s main point, then eliminate choices that add unsupported details or change location/time.'),
  ('644d9a42-917b-5af1-86cf-f5d5f5030de0', 3, null, '**Choice D is correct.** The passage presents a hypothesis that "differences related to the hyoid bone" — rigid in ocelots and somewhat flexible with a stretchy ligament in jaguars — "may help explain" why ocelots purr while jaguars roar. This summary captures the passage’s central claim about the hyoid-based explanation for the differing vocalizations.
**Choice A is incorrect.** That choice states a specific detail about hyoid rigidity versus flexibility but does not express the passage’s main idea that these differences may explain purring versus roaring.
**Choice B is incorrect.** Although the passage mentions a research hypothesis, it does not focus on researchers’ uncertainty; it focuses on the proposed explanation involving the hyoid.
**Choice C is incorrect.** This choice emphasizes only roaring and omits the comparison with ocelots and the broader claim that hyoid differences may explain the two species’ different sounds.
**Faster approach:** For main-idea questions, restate the passage in one sentence using the author’s main claim words (here, "hyoid" and "may explain"); eliminate choices that are merely details, partial claims, or that shift focus away from the central explanation.'),
  ('c0462a7b-1662-5162-9bf4-caa9bdce14f2', 0, null, '**Choice A is correct.** The passage explains that both “coyote” and “condor” are loanwords: each entered English via Spanish after originating in an Indigenous language (Nahuatl for coyotl → Spanish coyote → English, and Quechua kuntur → Spanish → English). This statement captures the passage’s central idea about the origin of the two words.
**Choice B is incorrect.** The passage gives only two examples and does not claim or provide evidence that Spanish adopted equal numbers of words from Nahuatl and Quechua.
**Choice C is incorrect.** The passage describes words entering English through Spanish after originating in Indigenous languages, not that Spanish words passed through English before entering Spanish.
**Choice D is incorrect.** The passage discusses origins and transmission routes, not any change in meaning when non‑Indigenous languages borrowed the words.
**Faster approach:** For main‑idea questions, summarize each sentence in a short phrase and pick the answer that matches that summary; eliminate choices that introduce unsupported comparisons or causal claims.'),
  ('8c5cbd94-74e0-5486-859d-10d2fc3dad95', 1, null, '**Choice B is correct.** The passage says the researchers measured infants’ heart rates and treated a reduced heart rate as evidence of relaxation; therefore a finding that infants’ heart rates were substantially lower during the lullaby than during the non-lullaby directly supports the claim that the lullaby relaxed the infants.
**Choice A is incorrect.** More irregular heart rates do not indicate relaxation and, in fact, would undermine the argument that the lullaby produced a calmer physiological state.
**Choice C is incorrect.** Parents’ preferences are subjective and do not provide direct physiological evidence that the infants themselves were more relaxed when hearing the lullaby.
**Choice D is incorrect.** The singer’s gender is irrelevant to whether the infants’ heart rates decreased; it does not directly support the claim about relaxation.
**Faster approach:** Focus on the measured outcome named in the passage (heart rate as a proxy for relaxation) and choose the answer that reports a direct change in that measure in the predicted direction.'),
  ('f899c6da-44cc-59b9-a682-cdfc8c1d0513', 2, null, '**Choice C is correct.** The quotation explicitly states that Mrs. Sommers "was not thinking at all" and describes her actions as governed by a "mechanical impulse" that freed her of responsibility, which directly supports the claim that she sometimes makes decisions without conscious deliberation.
**Choice A is incorrect.** Though it shows a moment of action (handing over a five-dollar bill), it does not indicate whether the action was taken without conscious thought; it focuses on the parcel’s size rather than her mental state.
**Choice B is incorrect.** This line emphasizes being absorbed in present needs, implying active attention to circumstances rather than an absence of thought or mechanical decision-making.
**Choice D is incorrect.** Mrs. Sommers'' careful examination of the stockings suggests deliberate scrutiny and pretense of thought, which contradicts the idea of acting without conscious deliberation.
**Faster approach:** For evidence questions about a character’s mental state, scan choices for explicit language about thinking (e.g., "not thinking," "mechanical impulse"); the quote that directly mentions absence of thought is the correct selection.'),
  ('a8d38c49-3475-52b9-b702-5a3d8a7a5d3d', 0, null, '**Choice A is correct.** The team’s conclusion depends on listeners reliably detecting acoustic differences between spontaneous and volitional laughter across cultures. If volitional laughter produced in natural social contexts often shares the same acoustic qualities (pitch, intensity fluctuation) as spontaneous laughter, then those shared qualities would make the two types harder to distinguish and would directly undermine the claim that the ability to tell them apart is universal.
**Choice B is incorrect.** This statement supports the study’s internal analysis by reporting a demographic factor had no effect; it does not weaken the universality claim.
**Choice C is incorrect.** This repeats evidence that spontaneous laughter has certain acoustic features, which would support—not weaken—the idea that listeners can identify it.
**Choice D is incorrect.** If acoustic features of spontaneous laughter are consistent within and across societies, that consistency supports universality, not undermines it.
**Faster approach:** Look for a quotation that introduces ambiguity or overlap between the two categories; the best weakeners say the categories share characteristics, so pick the choice that claims overlap in acoustic features.'),
  ('f4f265b9-a760-5d9d-96e5-9e990e79cc9a', 0, null, '**Choice A is correct.** The graph shows that forest area for each land-use class is lower in 1979 than in 2000: Class I–IV rises from about 350 square kilometers in 1979 to about 1,050 in 2000, Class VI rises from about 300 to about 750, and Class VII rises from about 250 to about 800. These increases across all three classes provide clear evidence of regrowth after the mid-1980s.
**Choice B is incorrect.** While Class I–IV and Class VII are somewhat closer in 1986 than in 1979, they are not notably similar in value, and the similarity does not demonstrate the post–mid-1980s regrowth described.
**Choice C is incorrect.** The difference between Class I–IV and Class VI in 2000 is a snapshot of relative areas, not direct evidence of regrowth after the mid-1980s.
**Choice D is incorrect.** Although there is a decrease from 1960 to 1979, that choice describes the initial decline, not the subsequent regrowth the sentence references.
**Faster approach:** Scan the graph for the pre- and post-regrowth years named in the passage (1979 vs. 2000); if all class lines rise from the earlier to the later year, choose the answer stating an increase across all classes.'),
  ('3a880c37-3c8f-5464-9b85-ce7acc31bae0', 2, null, '**Choice C is correct.** The sentence links two ideas: researchers haven’t observed Mammillaria in eastern and western Coahuila, and much of that landscape is notoriously inaccessible. The most logical completion is that the absence might reflect lack of exploration rather than true absence, so the perceived absence may be due to insufficient exploration of the region.
**Choice A is incorrect.** The sentence focuses on inaccessibility of the landscape as an explanation for nonobservation, not on misidentification or similarity to other species, so A introduces an unrelated reason.
**Choice B is incorrect.** This choice claims a systematic overestimation of species elsewhere; nothing in the passage suggests collection methods bias species counts, so B is unsupported.
**Choice D is incorrect.** The passage already states dense vegetation and high precipitation threaten Mammillaria survival, but the sentence specifically points to inaccessibility as an alternative explanation for nonobservation, not to environmental unsuitability in those parts of Coahuila.
**Faster approach:** Look for the clause that connects directly to the underlined cause word (here, “inaccessible”) and select the choice that restates its most straightforward implication (insufficient exploration).'),
  ('b6dfdb9c-45b4-56fe-80d0-a2ee91c4be7c', 3, null, '**Choice D is correct.** The sentence is a simple declarative statement about what the poem does: it performs or includes the first use of the word “dreamscape.” The present-tense verb "contains" agrees with the singular subject "The 1958 poem..." and yields a clear, idiomatic sentence: "The 1958 poem ... contains the first use..."
**Choice A is incorrect.** "Having contained" is a perfect participle that would require an auxiliary or a different sentence structure (e.g., "Having contained X, the poem..."), so it does not fit as the main verb of this declarative clause.
**Choice B is incorrect.** "To contain" is an infinitive and cannot serve as the finite main verb of this independent clause; it would make the sentence ungrammatical as written.
**Choice C is incorrect.** "Containing" is a present participle that would make the phrase a reduced relative clause (e.g., "the poem, containing the first use...") but as placed it does not supply the required finite verb and leaves the sentence incomplete.
**Faster approach:** For sentences describing what a noun does, try the simple present verb that agrees in number ("contains") before considering participles or infinitives.'),
  ('587f1617-d622-52dc-af4f-a1aefc7b5cb2', 2, null, '**Choice C is correct.** The subject is the singular noun phrase "an abstract cubist painting," so the verb must be singular; "has entered" is the singular present perfect form that correctly links the historical exhibition to its status "more than a century later." The present perfect expresses that the painting’s entrance into the Western art canon is a change that has occurred at some unspecified time before now and has relevance to the present.
**Choice A is incorrect.** "Were entering" is plural and past progressive, which disagrees with the singular subject and the sense that the change is completed by the present.
**Choice B is incorrect.** "Enter" is simple present plural; it does not agree with the singular subject and does not appropriately convey that the action has occurred by the present time.
**Choice D is incorrect.** "Have entered" is present perfect but uses the plural auxiliary "have," which disagrees with the singular subject.
**Faster approach:** Identify the subject’s number (singular vs. plural) and match verb number; then choose present perfect (has/have + past participle) when a past action has present relevance (phrases like "more than a century later").'),
  ('48e98338-1260-5392-bb8a-034a15852e07', 0, null, '**Choice A is correct.** The sentence after the blank begins an independent clause that introduces a contrasting situation: "With a pressure cooker pot, though, an airtight seal traps the vapor..." That clause should be a new clause introduced by the preposition "With," so a period before "With" correctly ends the preceding sentence and allows the clause to start. "vapor. With a pressure cooker pot, though, an airtight seal..." is grammatical and clear.
**Choice B is incorrect.** "vapor and with" creates an ungrammatical coordination: it incorrectly strings two constructions together and produces a run-on phrase that doesn’t fit the sentence structure.
**Choice C is incorrect.** "vapor, with" leaves the following phrase attached as a nonrestrictive modifier to the main clause, producing awkward punctuation and failing to set off the contrasting idea as a new clause as effectively as a period does.
**Choice D is incorrect.** "vapor with" produces a fused construction that lacks necessary punctuation to introduce the contrasting clause and results in a confusing sentence flow.
**Faster approach:** When a following clause introduces a new, contrasting scenario, start a new sentence with a prepositional phrase (use a period + capitalized preposition) rather than trying to attach it with commas or conjunctions.'),
  ('2c2a50c4-82c1-5312-8d68-fb5ac64477dc', 2, null, '**Choice C is correct.** The sentence is a quotation that ends with the word direction and is followed by a closing quotation mark and then a comma in the surrounding sentence; when a quoted phrase ends a clause that continues the surrounding sentence, Standard English punctuation requires the closing quotation mark followed by the comma, then the sentence continues. Here the quoted material ends the clause introducing the year 1912, so the correct punctuation is a closing quotation mark then a comma and then the sentence continues—rendered as $"direction",$ which is choice C.
**Choice A is incorrect.** It places only a closing quotation mark with no following comma, which fails to provide the required comma that separates the quotation from the continuation of the sentence ("in 1912, for instance, judges recognized...").
**Choice B is incorrect.** It adds an extraneous conjunction "and," immediately after the closing quotation mark, creating an ungrammatical and unnecessary connector between the quotation and the rest of the sentence.
**Choice D is incorrect.** It places a comma inside the quotation mark ("direction,"), which would be correct only if the comma were part of the quoted material. Here the comma functions as punctuation of the surrounding sentence and therefore must come after the closing quotation mark, not inside it.
**Faster approach:** When a quotation ends a clause but the sentence continues, always put the closing quotation mark first and then the needed comma or period for the main sentence (i.e., choose the option with $"...",$ rather than $"...,"or$"..." and ...). This rule applies to any question about punctuation at the end of a quotation that connects to the rest of the sentence.'),
  ('34b48f5b-c602-5294-a28a-c05664408532', 3, null, '**Choice D is correct.** The phrase that begins the sentence ("With a blend of ... such as floor-to-ceiling windows") is an introductory prepositional phrase and must be closed with a comma before the main clause. Placing a comma after "windows" correctly ends the introductory material and allows the main clause "transitional design splits the difference..." to follow; "transitional" properly modifies "design."
**Choice A is incorrect.** A semicolon joins two independent clauses or separates complex list items; the material before the mark is an introductory phrase, not an independent clause, so a semicolon is wrong.
**Choice B is incorrect.** A period would leave the initial "With..." segment as a sentence fragment; that introductory prepositional phrase cannot stand alone as its own sentence.
**Choice C is incorrect.** An em dash would create an unnecessary and nonstandard break after an introductory phrase; the conventional punctuation here is a comma.
**Faster approach:** Ask whether the words before the blank form an introductory phrase; if they do, choose the comma that closes the introductory phrase and begins the main clause.'),
  ('6f0ca144-8b5b-5c8f-b7f6-c0f3e0c7d789', 2, null, '**Choice C is correct.** The phrase "twentieth-century US artists Thomas Hart Benton and Jackson Pollack" is an essential noun phrase identifying which artists are meant; no internal punctuation is required. Inserting this phrase into the sentence yields a grammatically correct construction: "Paintings by the renowned twentieth-century US artists Thomas Hart Benton and Jackson Pollack were featured..."
**Choice A is incorrect.** The commas in "artists Thomas Hart Benton, and Jackson Pollack," set off the names improperly: the comma before "and" is unnecessary, and the trailing comma interrupts the sentence flow.
**Choice B is incorrect.** A colon after "artists" is inappropriate in this sentence structure because the clause that follows is not a separate explanatory or list structure set off from the main clause; additionally, the following comma is extraneous.
**Choice D is incorrect.** A single comma before the names would imply a nonrestrictive appositive, which would require a closing comma after "Pollack" as well; because that closing comma is missing, the punctuation is incorrect.
**Faster approach:** Determine whether the names are essential (restrictive) or nonessential: if essential, use no commas; if nonessential, set off the names with commas on both sides. Use that rule to eliminate incorrect punctuation quickly.'),
  ('3e2ffc8e-026e-522c-97eb-44dd1a12f55c', 3, null, '**Choice D is correct.** The phrase "In doing so," indicates that by joining the Navy and serving aboard the USS Pinola, Ahoy accomplished the subsequent result: earning a place in history. This transition clearly links the action (his service) with its consequence (his historical significance), so the sentence reads logically and coherently.
**Choice A is incorrect.** "In any case," signals a dismissal or shift that does not indicate causation; it would break the logical connection between his service and his historical status.
**Choice B is incorrect.** "Finally," suggests a temporal or concluding sequence rather than a cause-and-effect relationship, making the sentence sound like an unrelated conclusion instead of a result of his service.
**Choice C is incorrect.** "For instance," introduces an example and would require the preceding statement to be a general claim; here the sentence needs to show that his service produced the historical outcome, so "For instance" is inappropriate.
**Faster approach:** Identify whether the second clause expresses result/ consequence; if so, choose a causal transition (e.g., "In doing so," or "As a result,").'),
  ('c3e32d91-c747-52e4-b3ae-f2d8a8ba3ca2', 2, null, '**Choice C is correct.** The sentence provides a direct comparison between two wind farms'' outputs, so the transition "By comparison," signals that the second sentence will contrast the Hornsea Project One’s larger output (1,218 MW) with the London Array’s 630 MW. This makes the relationship between the two facts clear and logical.
**Choice A is incorrect.** "As a result," indicates a cause-and-effect relationship, but the second sentence does not follow from the first causally; it simply presents a different data point.
**Choice B is incorrect.** "That is," is used to restate or clarify the preceding idea; here the second sentence is not a clarification of the first but a contrasting data point.
**Choice D is incorrect.** "For instance," introduces an example of a general statement; the Hornsea farm is not being given as an example of the London Array and the sentence instead compares two specific values.
**Faster approach:** For comparison/contrast questions, look for numerical or contrasting information; if the second clause gives a different or larger/smaller value, choose a comparative transition like "By comparison."'),
  ('fb7382fd-20db-55f0-a3e5-671a584e2ef0', 0, null, '**Choice A is correct.** The sentence before states that Molina and Rowland’s research was “extremely influential,” and the following clause gives a specific example of that influence: it “laid the foundation for a 1987 treaty.” The transition “Specifically,” signals that the clause to follow will be a particular illustration of the prior claim, so it fits the logical relationship.
**Choice B is incorrect.** “Regardless,” signals dismissal or contrast with a preceding idea; here the second clause elaborates on the first, so no contrast is intended.
**Choice C is incorrect.** “Earlier,” signals a time reference that conflicts with the timeline (the 1987 treaty came after the 1974 discovery), so it is inappropriate.
**Choice D is incorrect.** “However,” introduces a contrast, but the second clause supports and exemplifies the claim that the research was influential, so a contrasting transition is wrong.
**Faster approach:** Identify the relationship between sentences (example/support vs. contrast vs. time). Pick the transition that matches that relation—here, an example/support relation calls for “Specifically.”'),
  ('e4f2795c-c9ab-59e0-aa08-a6f6b0983664', 0, null, '**Choice A is correct.** The sentence begins with a general statement about sleek vehicles being more aerodynamic, and the clause that follows describes a specific instance, the Airbus A320’s nose, that illustrates that general point. The transition "for example" appropriately signals that the Airbus is an instance supporting the general claim, so "The streamlined nose of the Airbus A320 jet, for example, helps it glide..." is logical and grammatically smooth.
**Choice B is incorrect.** "Additionally" implies adding another similar point, but the sentence is providing a specific example of the general statement rather than simply adding more information, so this transition is less precise.
**Choice C is incorrect.** "Meanwhile" suggests a temporal or simultaneous contrast between events; it does not signal that the Airbus is an example supporting the generalization and therefore is inappropriate here.
**Choice D is incorrect.** "However" introduces a contrast, which would contradict the preceding statement; because the clause about the Airbus supports (not contradicts) the idea that sleek vehicles are more aerodynamic, "however" is incorrect.
**Faster approach:** When a sentence moves from a general claim to a specific instance, choose a phrase that signals an example ("for example," "for instance")—this quickly identifies A as the correct transition.'),
  ('bad11dfc-3e21-5fe0-b22e-70e66b518723', 1, null, '**Choice B is correct.** It accurately synthesizes the given notes by naming the researchers and reporting their finding of 146 springtail species in Puerto Rico, then specifies that the count includes one species in genus Hemisotoma and three in genus Sphaeridia, matching the notes exactly.
**Choice A is incorrect.** It is a sentence fragment and omits the study and total-species finding; it also leaves the clause about Sphaeridia incomplete.
**Choice C is incorrect.** It claims the researchers wanted to know the numbers specifically for those genera, which is not stated in the notes (the notes report findings, not the researchers'' initial question).
**Choice D is incorrect.** Although true that Sphaeridia has more species than Hemisotoma, this choice omits the researchers and frames the comparison as a contrast that downplays the primary finding (the total of 146 species).
**Faster approach:** Look for the option that includes the researchers and the total numeric finding and then verifies the specific genus counts; eliminate fragments or choices that introduce unsupported intentions or omit key facts.'),
  ('78d8a874-cd28-5c63-a20d-654d7d6f3304', 2, null, '**Choice C is correct.** It directly defines a merchant vessel as "any ship hired to carry cargo or passengers" and immediately gives the examples "bulk carriers, cruise liners, and oil tankers," which exactly matches the relevant notes and accomplishes both parts of the student’s goal.
**Choice A is incorrect.** Although factually related, it only states a statistic about ships registered in Greece in 2021 and does not provide a clear definition or examples of merchant vessels.
**Choice B is incorrect.** This choice discusses how carrying capacity is measured and mentions vessel types, but it does not provide the definition of a merchant vessel (that it is hired to carry cargo or passengers).
**Choice D is incorrect.** This gives a combined carrying-capacity statistic for Greek vessels, which is relevant background but does not explain what a merchant vessel is or give examples.
**Faster approach:** Look for the sentence that both states a definition ("is any...") and lists examples; that single sentence will best meet the dual requirement of defining and exemplifying.'),
  ('2fd75b64-c9b1-5dd6-b6db-6c54aa0f23bd', 0, null, '**Choice A is correct.** It explicitly contrasts the two songs by acknowledging that both are protest songs and then points out their different subjects: Poor Miner’s Farewell focuses on Kentucky coal miners, while Bring Him Back Home focuses on freeing Nelson Mandela. Both pieces of information are drawn directly from the student’s notes and together accomplish the goal of showing how the songs differ.
**Choice B is incorrect.** Although it accurately summarizes one song, it does not contrast the two songs, so it fails to accomplish the student’s stated goal.
**Choice C is incorrect.** This statement highlights a similarity (both raised awareness) rather than contrasting the songs, so it does not meet the prompt.
**Choice D is incorrect.** Like choice B, this choice accurately describes only Poor Miner’s Farewell and does not compare or contrast it with Bring Him Back Home.
**Faster approach:** For contrast tasks, look for an answer that names both items and then states how they differ; eliminate choices that describe only one item or that state only similarities.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Aug 2024 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('58b8d714-733d-583e-a2a1-2e9741596bb0', 'PeaklyTest Aug 2024 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Aug 2024 PeaklyTest · 27 questions · 32 minutes', 32, 211, true, 'PeaklyTest Aug 2024 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('216b841b-6a0a-5fc4-a67b-fe89d9e8bb56', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text with the most logical and precise word or phrase?', '["imitate", "design", "illuminate", "substitute"]'::jsonb, 1, 'The fossil remains of the individual known as KNM-KP 271, discovered in Kenya in 1965, can help paleoanthropologists not only identify steps in the evolution of hominids but also _____ the Pliocene epoch generally, revealing important details about the time in which KNM-KP 271 lived.'),
  ('8b102502-af64-5145-993a-575de4281d55', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text with the most logical and precise word or phrase?', '["summations", "conjectures", "exemplifications", "conclusions"]'::jsonb, 2, 'Before the Mariner 2 mission completed a successful flyby of Venus in 1962, astronomers'' ideas about the planet were little more than _____. Venus’s atmosphere is so thick that Earth-based observations had yielded very little information about the planet.'),
  ('cffe9200-7c4d-5476-8805-db95d3660ff5', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text with the most logical and precise word or phrase?', '["ambivalent", "counterfactual", "analogical", "associative"]'::jsonb, 3, 'The work of Tobias Gerstenberg et al. on tracking eye movements supports a theory that people engage in _____ thinking when making causal judgments: when subjects were asked to look at two colliding billiard balls and judge whether one caused or prevented the other’s movement through a gate, their eyes looked at where the target ball would have gone if the ball that altered its path did not exist.'),
  ('cbfe7d51-bbad-5430-af36-a48a00010ba4', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice best describes the function of the two underlined portions in the text as a whole?', '["They describe the subjects, one physical and one abstract, of a comparison that extends throughout the text.", "They symbolize two attitudes, one logical and one emotional, that are contrasted throughout the text.", "They indicate potential reactions, one hoped for and one feared, to a decision the speaker considers throughout the text.", "They provide examples, one literal and one figurative, of a change that the speaker describes throughout the text."]'::jsonb, 4, 'The following text is from Sarojini Naidu’s 1896 poem “Alabaster.”
Like <u>this alabaster box</u> whose art
Is frail as a cassia-flower, is <u>my heart,</u>
Carven with delicate dreams and wrought
With many a subtle and exquisite thought.'),
  ('c6d99ba9-aeb8-5e21-8691-575db7570efd', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice best describes the overall structure of the text?', '["It draws a distinction between the sizes of the humpback whale and the fin whale and then presents a feature that they have in common.", "It details a relationship between humpback and fin whales and krill and then discusses an unexpected consequence of a change in baleen whale populations.", "It discusses a unique feature of the humpback whale and how the lack of that feature in the fin whale explains differences in the two species’ behavior.", "It describes a characteristic shared by all baleen whales and then illustrates a difference between the humpback whale and the fin whale that is relevant to that characteristic."]'::jsonb, 5, 'Like all species of baleen whales, the humpback whale feeds on tiny creatures known as krill by filtering water through bristlelike keratin structures called baleen plates. In this way, baleen whales can eat up to 30 percent of their total mass per day. And while no one would call the humpback whale small— it can have a mass as high as 30,000 kg— it is one of the smaller baleen whales and is much smaller than the fin whale, which can weigh a whopping 80,000 kg and consume as much as 24,000 kg of krill per day.'),
  ('d3e1d4e1-39c7-53f3-85ca-0e7ad30b9cb5', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It defines a term used earlier in the sentence.", "It addresses a potential criticism of a claim made earlier in the sentence.", "It elaborates on a claim made earlier in the sentence.", "It acknowledges an exception to the general principle proposed earlier in the sentence."]'::jsonb, 6, 'In what is now Minnesota, the Shakopee Mdewakanton Sioux Community operates the Hocokata Ti, a cultural center. Relying on traditional knowledge to guide the design of exhibits, this institution presents Dakota history and culture to the tribe’s citizens. The Comanche Nation, a tribe in Oklahoma, employs a similar strategy in its own cultural center. Both centers contrast with museums that aren’t Indigenous-led; <u>when displaying Indigenous artifacts, such museums tend to anticipate mainly non-Indigenous</u> <u>audiences and rely on Euro-centric strategies for designing exhibits.</u>'),
  ('5cea636d-84e9-5c36-a40e-ce3829c7918c', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Based on the texts, both authors would most likely agree with which statement?', '["A collaborative approach to conservation is likely to help reduce the predicted temperature increases in the Great Lakes region.", "In the Great Lakes region, conservation efforts focused on the northern wild rice plant are likely to be more effective than those focused on the American crow.", "Natural resources conservation projects are likely to benefit from collaboration between tribal and government groups.", "In the Great Lakes region, it is more important to focus conservation efforts on the northern wild rice plant than it is on the American crow."]'::jsonb, 7, '**Text 1**
A conservation group representing 11 tribal nations in the Great Lakes region reported to various state and federal natural resources agencies operating in the region that the northern wild rice plant (manoomin in the Ojibwe language) will likely fare significantly worse than the American crow (aandeg in Ojibwe) due to rising temperatures over the next 50 years. This collaborative approach has helped build trust between government and tribal groups, which will likely improve the quality of any joint conservation projects.

**Text 2**
State and federal natural resources agencies are increasingly incorporating traditional ecological knowledge from tribal groups in the agencies'' plans to address threats to natural resources due to increasing temperatures. This approach has helped build positive relationships between tribal groups and these agencies and furthermore tends to lead to better conservation outcomes.'),
  ('fe66ef32-ac24-5b73-a94f-88cfba270ac2', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Based on the text, which choice best expresses the narrator’s characterization of the Seine?', '["As the journey progressed from Paris to the countryside, the waters of the Seine gradually cleared.", "The journey along the Seine is mostly peaceful, but the current intensifies briefly under the Point du Jour.", "The waters of the Seine are more confined and rough in Paris than they are in the countryside.", "The Seine’s loveliness is surpassed only by that of Paris."]'::jsonb, 8, 'The following text is adapted from Guy de Maupassant’s 1884 short story “A Recollection,” from the collection Guy de Maupassant Short Stories (translated by Albert M.C. McMaster et al. in 1903). The narrator is taking a boat down the Seine river from Paris, France, to the surrounding countryside.

I took up a position in the bows [front of the boat], standing up and looking at the quays, the trees, the houses and the bridges disappearing behind us. And suddenly I perceived the great viaduct of Point du Jour which blocked the river. It was the end of Paris, the beginning of the country, and behind the double row of arches the Seine, suddenly spreading out as though it had regained space and liberty, became all at once the peaceful river which flows through the plains, alongside the wooded hills, amid the meadows, along the edge of the forests.'),
  ('b7222dd4-7cb4-5b77-b34d-41b0466b4546', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which finding, if true, would most directly support the second research team’s hypothesis?', '["A study using obstructions that created large vortices in low-visibility conditions found that the Synodontis macropunctata, which has a relatively wide head, bumped into more than half of the obstructions.", "A study using obstructions that created large vortices in low-visibility conditions found that some specimens of the intermediate-headed dusky smooth-hound (Synodontis macropunctata) bumped into the obstructions more often than other specimens of the same fish did.", "A study using obstructions that created large vortices in low-visibility conditions found that the wide-headed Synodontis macropunctata bumped into obstructions more often than the intermediate-headed dusky smooth-hound (Synodontis macropunctata) did.", "A study using obstructions that created large vortices in low-visibility conditions found that the intermediate-headed dusky smooth-hound (Synodontis macropunctata) bumped into the obstructions just as often as the wide-headed Synodontis macropunctata did."]'::jsonb, 9, 'Water flowing around an obstruction creates vortices (patterns of swirls) of varying size; by detecting the vortices, fish can determine the size and position of the obstruction. Testing by Yuzo R. Yanagisuru, Otar Akanyeti, and James C. Liao using models of three head shapes—narrow (low ratio of width to length), intermediate, and wide (high ratio of width to length)—showed that for large vortices, fish with intermediate heads would be better able than wide-headed fish to distinguish between vortices and general turbulence in the water. A second research team has therefore hypothesized that in low-visibility conditions, intermediate-headed fish will be more likely than wide-headed fish to detect obstructions that create large vortices.'),
  ('a78b6793-7480-5d39-b1b6-fb55f64eafcf', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which finding, if true, would most directly support the underlined claim?', '["Reckoning and Resilience and Across County Lines were curated to emphasize works that are not owned by the Nasher Museum.", "Truong is a painter, Carter is a photographer, and Stein is a sculptor.", "The Nasher Museum has a world-class collection of contemporary art that includes many paintings and sculptures from artists both inside and outside North Carolina.", "Carter is a North Carolina photographer, as were all of the artists featured in Across County Lines."]'::jsonb, 10, 'The Reckoning and Resilience (2022) exhibition at Duke University’s Nasher Museum of Art in Durham, North Carolina, is dedicated to the work of thirty North Carolina artists, including Lien Truong, Kennedi Carter, and Meg Stein. <u>Although the Nasher Museum has focused exhibitions entirely on North Carolina</u> <u>artists before, as it did previously in the photography exhibition Across County Lines, the breadth of</u> <u>disciplines in Reckoning and Resilience sets it apart.</u>'),
  ('6cf41d8e-9903-5b51-944c-f8bbc5e75182', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which finding, if true, would most directly weaken the student’s claim?', '["A Yupno speaker points in opposite directions when indicating a past event versus a future event.", "Some Yupno grammatical structures used when talking about time are also used in Spanish.", "When Yupno speakers who are outdoors use gestures to refer to the future, they point uphill from their current location regardless of which way they are facing.", "Although Yupno speakers and Spanish speakers both use gestures to indicate orientation in time, Yupno speakers tend to use fewer gestures overall when speaking than Spanish speakers do."]'::jsonb, 11, 'Rafael Núñez and colleagues studied how members of the Yupno, an Indigenous group in Papua New Guinea, conceptualize time. The researchers recorded Yupno speakers explaining certain temporal words and phrases, such as abjiuk sonda, a present-oriented expression that translates to “this week,” and coded each speaker’s manual gestures. Previous research has found a tendency in many cultures to make temporal distinctions using spatial concepts and gestures, particularly along egocentric axes (i.e., relative to the orientation of the speaker): for instance, Spanish speakers often refer to the left/right axis to describe events in time. In an anthropology paper, a student claims that the tendency toward ego-based conceptualizations of time is universal.'),
  ('60121067-5439-54c6-accf-aea1ab5f2153', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice most logically completes the text?', '["the proportion of younger speakers who use a Spanish dialect specific to New York City is higher in neighborhoods where many languages are spoken than in neighborhoods where Spanish and English predominate.", "both the number of languages spoken in New York City and the number of dialects of each of those languages will increase over time.", "Spanish used by younger speakers in New York City tends to have more words borrowed from other nonmajority languages than borrowed from English.", "younger speakers of Spanish in New York City would be more likely to use a dialect specific to New York City than older speakers living in the same neighborhood would be."]'::jsonb, 12, 'Over 600 languages are spoken in New York City in addition to English—one can find Bambara spoken in the neighborhood of Kingsbridge, for example, or Ghale in Jackson Heights. English is the most common, with 65% of New Yorkers speaking it at home; Spanish is second, at 20%. A linguist hypothesizes that a Spanish dialect—a variation differing from the parent language in some of its vocabulary, pronunciation, and grammar—has developed in New York City, partly due to its linguistic interaction with English. Previous research shows that younger speakers of nonmajority languages are more likely to borrow words from the majority language of a region than are older speakers. If the linguist’s hypothesis is correct, it is therefore likely to be the case that _____'),
  ('c118946f-fe05-5e58-a0fc-abb8b29fc189', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice most logically completes the text?', '["Le Morte d''Arthur is more historically accurate than History, because the Mabinogion had not been written when Geoffrey of Monmouth was writing his work.", "Malory did not use Preiddeu Annwfn as a source for information he presented about the Round Table.", "Geoffrey of Monmouth was unaware of stories of the Round Table when composing his History, though historians know that works containing such stories were available to him.", "Geoffrey of Monmouth’s accounts of Arthurian legends in his History are more similar overall in content to the accounts in the Mabinogion than they are to the accounts in Roman de Brut."]'::jsonb, 13, 'Arthurian legends (tales related to the character of King Arthur) derive from many sources, such as Preiddeu Annwfn, composed around 900, and the Mabinogion from the 12th and 13th centuries. One of the most significant sources, Geoffrey of Monmouth’s History of the Kings of Britain, was written in Latin in the 1130s; some material from it was later adapted by the Norman poet Wace into the Roman de Brut in 1155. But while no source before 1155 includes references to the famous Round Table at which Arthur’s knights assembled, both the Roman de Brut and Sir Thomas Malory’s 15th-century compilation of Arthurian legends, Le Morte d’Arthur, do. It can therefore be inferred that _____'),
  ('3ce54a6d-2851-541e-9b2e-496f60ed74c6', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice most logically completes the text?', '["keep the amount of silver in Sidonian coins consistent with that in coins minted in 367 BCE but decrease their weight.", "proclaim that the percentage of silver in coins suitable for trade would be raised to a threshold higher than 80%.", "fund the mining of some copper deposits that were not available to Ba''alsillem II.", "begin minting heavier coins with a proportion of silver to copper similar to that in coins minted in 367 BCE."]'::jsonb, 14, 'An analysis by Alain Elayi and colleagues of coins minted in Sidon in the fifth and fourth centuries BCE reveals a change in their composition over time: while a coin from circa 450 BCE contains about 98% silver and 1% copper, a coin from 367 BCE (the end of Ba’alsillem II’s reign) contains 74.2% silver and 24.7% copper, giving it a relatively yellowish appearance that traders would have noticed. Because coins with a silver content below 80% were widely considered unsuitable for trade, Elayi et al. speculate that a crisis in confidence in the currency occurred in Sidon around 367 BCE, which was likely relieved—despite Sidon’s persistent oppressive financial obligations—as a result of Ba’alsillem II’s successor Abd’astart I’s decision to _____'),
  ('124b0a7a-addb-5bd4-9e91-b1dd040f3f58', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["influence", "influence, and", "influence,", "influence and"]'::jsonb, 15, 'Today, the Michelin Guide is widely known as the arbiter of fine dining, but when it was created in 1900, it was little more than a marketing gimmick; brothers Andre and Edouard Michelin sought to increase profits for their tire company by encouraging their customers to drive across France, visiting the guide’s recommended hotels and restaurants along the way. Nevertheless, the guide soon grew in scope and _____ its modest French eateries were replaced with some of the most esteemed restaurants from around the world, including La Yeon in Seoul and Sushi Shikon in Hong Kong.'),
  ('f1ba05c7-dd0e-5037-a56d-027ec8fd08fa', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["study", "has studied", "studies", "is studying"]'::jsonb, 16, 'Interest in mechanotransduction, the mechanism by which cells sense and convert mechanical stimuli into biochemical signals, is expanding because of innovative work by biomedical scientists. Many of whom, like neuroscience and biophysics expert Elba Serrano, ______ this mechanism to better understand how the body’s neurological and biomechanical systems interact.'),
  ('3246ca31-1250-554f-b0ff-eb9db0b6f97f', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["song:", "song,", "song;", "song"]'::jsonb, 17, 'If you had turned on the radio in the winter of 1970, chances are you would have heard the hit _____ “Oh What a Day” by the Dells. The song spent ten straight weeks on the Billboard Hot 100 chart that year.'),
  ('bd41b3b3-46dd-584d-844b-302abbff78dd', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["inequality, for instance;", "inequality; for instance,", "inequality, for instance,", "inequality for instance;"]'::jsonb, 18, 'Integrating insights from economics and psychology, researchers in the field of behavioral economics explore a variety of topics. Lucia Macchia of the University of Oxford studies socioeconomic _____ other researchers investigate areas such as organizational behavior and personal finance.'),
  ('dc5274e7-424a-5a80-b8db-dcf7314c82f1', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Kittredge, however;", "Kittredge; however,", "Kittredge. However,", "Kittredge, however,"]'::jsonb, 19, 'William Kittredge’s short essay on “krummholz,” a word referring to twisted and stunted trees growing near the tree line, is included in the collection Home Ground: A Guide to the American Landscape. The book wasn’t written solely by _____ other authors, such as Linda Hogan and Barry Lopez, also contributed essays.'),
  ('b5bee7dc-e9b9-588a-a5f4-6c398ab0da07', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["suggests", "suggested", "suggesting", "has suggested"]'::jsonb, 20, 'Recent pollen analyses of the Aran Islands have led some researchers to propose that the now treeless islands were once wooded. This hypothesis _____ that certain trees, such as P. sylvestris, survived without interruption or human intervention throughout the Holocene cannot stand, researchers Michael O''Connell and Karen Molloy counter, unless other explanations can first be ruled out.'),
  ('0b669e33-7b1f-5d41-9b1f-7bd5f85f6616', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text with the most logical transition?', '["Second,", "Nevertheless,", "Indeed,", "Instead,"]'::jsonb, 21, 'With his room-sized installation Unicorn/My Private Sky, Norwegian artist Borre Saethre succeeds in creating a whimsical yet perplexing experience. _____ when visitors set foot inside the fantastically blue room and encounter the life-sized stuffed unicorn preening at the far end of it, they are both dazzled and confused as if stepping into a strange and enchanting new world.'),
  ('4da75bfc-abb4-5d95-ba4d-8bf763ae9717', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice completes the text with the most logical transition?', '["Nonetheless,", "On the other hand,", "Additionally,", "More often,"]'::jsonb, 22, 'Mountain climbing routes that incorporate metal rungs and cables are known as via ferratas, from the Italian phrase for “iron path.” As climbing these routes has shifted from a mode of travel to a sporting activity, modern via ferratas are rarely designed to simply reach a summit. _____ new routes favor recreation over utility, aiming to provide a challenging climb or showcase dramatic scenery.'),
  ('b8b0a82e-3ec9-5d28-a1d4-7fd1d49c1957', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'The student wants to use a quotation to refute the claim that slow TV programs are boring. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["While some have praised slow TV for affording “a visceral kind of armchair tourism,” others have called it “the world’s most boring television.”", "Far from boring, slow TV programs can provide a “visceral kind of armchair tourism,” as Heller puts it, whereby viewers can watch reindeer migrations in real time.", "With broadcasts of ordinary events, like reindeer migrations, occurring in real time, slow TV just might be “the world’s most boring television.”", "Reinflytting can afford a “visceral kind of armchair tourism,” as Heller puts it."]'::jsonb, 23, 'While researching a topic, a student has taken the following notes:

Documentary TV programs in the slow TV genre consist of uninterrupted broadcasts of ordinary events in real time.
Reinflytting is a Norwegian slow TV program.
The 9-day-long program documented a wild reindeer migration from their winter to summer pastures.
It first aired in 2017.
Slow TV has been called “the world’s most boring television.” American journalist Nathan Heller praises it, writing that “it affords a visceral kind of armchair tourism.”'),
  ('39396f9b-6825-543e-888a-3da3a2f3dec3', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'The student wants to specify how many chromosomes the fennec fox has. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The fennec fox (Vulpes zerda) and the red fox (Vulpes vulpes) both have chromosomes, but the fennec fox has more than the red fox does.", "The fennec fox (Vulpes zerda) has sixty-four chromosomes.", "The fennec fox’s chromosomes contain genes, which are critical to determining an organism’s physical traits.", "The red fox, a species of fox, has thirty-four structures called chromosomes."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

Chromosomes are cellular structures that contain genes. Genes carry critical instructions for determining an organism’s physical traits.
Members of the same species typically have the same number of chromosomes.
The fennec fox (Vulpes zerda) and the red fox (Vulpes vulpes) are species of foxes.
The fennec fox has sixty-four chromosomes.
The red fox has thirty-four chromosomes.'),
  ('1951779b-6740-5bbd-8a0d-09c89b265e64', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'Which choice most effectively uses information from the given sentences to describe a color that was popular at 2021 London Fashion Week?', '["Shades of delicate petal pink and stirring ocean blue have both been featured in Fashion Week reports prepared by color consultants.", "Each Fashion Week, color consultants compile reports on the colors that have been popular among designers.", "The shade favored by designers at 2021 London Fashion Week was a departure from the warm, soft shade of delicate petal pink that had proved popular at 2018 New York Fashion Week.", "At 2021 London Fashion Week, many designer collections featured a cool, bright shade of stirring ocean blue."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

At London and New York Fashion Weeks, fashion designers debut new clothing collections. Color consultants create trend reports on the popular colors at a given Fashion Week.
A report on 2018 New York Fashion Week noted the popularity of a delicate petal pink shade that was warm in tone and soft in intensity.
A report on 2021 London Fashion Week noted the popularity of a stirring ocean blue shade that was cool in tone and bright in intensity.'),
  ('1be64620-27e5-5523-bbbb-783e31c344c6', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'The student wants to place Einstein’s argument within its historical context. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["During the dawn of quantum theory, Einstein maintained the independent reality of some subatomic entities, although Bohr’s opposing interpretation would become the widely accepted view.", "The attendees of the 1927 Solvay Conference were among the preeminent scientists of their era, including Einstein, who opposed Bohr’s proposal.", "In 1927, Einstein and Bohr engaged in a famous debate; Bohr’s argument, later called, the Copenhagen interpretation, would remain popular decades after.", "At the 1927 Solvay Conference on Physics, Einstein disagreed with Bohr’s argument that subatomic entities like electrons had a reality independent of observation."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The fifth Solvay Conference on Physics was held in 1927.
It brought together twenty-nine of the era’s preeminent scientists to discuss the emerging field of quantum theory.
The conference famously featured a debate between physicists Albert Einstein and Niels Bohr. Bohr proposed that subatomic entities like electrons had only probable realities until they were observed.
Einstein argued that subatomic entities like electrons had a reality independent of observation. Bohr’s position, later called the Copenhagen interpretation, remains the most widely accepted theory of quantum mechanics.'),
  ('e60f59f9-9e0a-5601-9c9b-f16fd684a336', '58b8d714-733d-583e-a2a1-2e9741596bb0', 'The student wants to make a generalization about minerals. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Based on their Mohs scale numbers, topaz (8) is harder than apatite (5), and apatite is harder than calcite (3).", "Topaz can leave visible scratches on calcite, which is why topaz has a higher number than calcite on the Mohs scale of mineral hardness.", "Any mineral with a Mohs number of 8, like topaz, can scratch a mineral with a Mohs number of 5, like apatite.", "The Mohs scale can be used to order calcite, topaz, and apatite by their ability to scratch other minerals."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

The Mohs scale of mineral hardness is a ten-point scale that orders minerals by hardness based on their ability to scratch other minerals.
Minerals with larger numbers are harder than minerals with smaller numbers and can leave visible scratches on them.
Minerals with smaller numbers are softer than minerals with larger numbers and cannot leave visible scratches on them.
The mineral calcite has a Mohs scale number of 3.
The mineral apatite has a Mohs scale number of 5.
The mineral topaz has a Mohs scale number of 8.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('216b841b-6a0a-5fc4-a67b-fe89d9e8bb56', 2, null, '**Choice C is correct.** The sentence says the fossil remains can do one thing (identify steps in evolution) and can also do another that reveals details about the Pliocene epoch. "Illuminate" means to make clear or shed light on, which fits perfectly: fossils can clarify (illuminate) aspects of the Pliocene. The sense is precise and parallel to "identify steps," both verbs describing ways fossils provide information.
**Choice A is incorrect.** "Imitate" means to copy or mimic, which makes no sense for fossils providing information about an epoch.
**Choice B is incorrect.** "Design" means to plan or create, which does not match what fossil evidence does for an epoch.
**Choice D is incorrect.** "Substitute" means to replace; fossils do not replace the Pliocene epoch or its study, so this is not appropriate.
**Faster approach:** Substitute each choice into the sentence; eliminate any verb that implies action fossils cannot perform (design, imitate, substitute), leaving the only plausible meaning: "illuminate."'),
  ('8b102502-af64-5145-993a-575de4281d55', 1, null, '**Choice B is correct.** The sentence contrasts limited observational data with the nature of astronomers'' ideas about Venus; because Earth-based observations yielded very little information, astronomers'' ideas would have been speculative. "Conjectures" precisely means guesses or hypotheses made with incomplete evidence, which fits the context.
**Choice A is incorrect.** "Summations" means summaries or totals; it doesn’t convey the speculative, uncertain quality implied by the lack of information.
**Choice C is incorrect.** "Exemplifications" refers to examples or illustrations, which is unrelated to the idea that astronomers were merely making speculative claims.
**Choice D is incorrect.** "Conclusions" implies firm, settled judgments; this contradicts the clause that Earth-based observations yielded very little information and therefore would not support definitive conclusions.
**Faster approach:** Substitute a simple synonym (e.g., "guesses") into the blank and choose the answer with matching meaning; this quickly rules out words implying certainty or unrelated senses.'),
  ('cffe9200-7c4d-5476-8805-db95d3660ff5', 1, null, '**Choice B is correct.** The sentence describes looking at where a target ball "would have gone if the ball that altered its path did not exist," which expresses consideration of an alternative outcome contrary to actual events. That kind of reasoning is called "counterfactual" thinking—imagining what would have happened under different circumstances—so "counterfactual" is the most precise fit.
**Choice A is incorrect.** "Ambivalent" means having mixed or uncertain feelings; it does not capture the idea of imagining alternate outcomes or hypothetical scenarios described in the passage.
**Choice C is incorrect.** "Analogical" refers to reasoning by comparison between similar cases; the passage is about imagining an alternate history for the same event, not drawing an analogy to another case.
**Choice D is incorrect.** "Associative" refers to linking ideas or memories by association, which does not specifically denote imagining a contrary-to-fact outcome as required here.
**Faster approach:** Focus on the clause "would have gone if... did not exist"—phrases that describe hypothetical alternate outcomes signal the term "counterfactual," so pick that option immediately.'),
  ('cbfe7d51-bbad-5430-af36-a48a00010ba4', 0, null, '**Choice A is correct.** The two underlined words name the two terms being compared: "alabaster" (the physical alabaster box) and "my heart" (an abstract, inner thing). The simile "Like this alabaster box ... is my heart" makes a direct comparison between a tangible object and the speaker’s inner state, so the underlined items serve as the physical and abstract subjects of that extended comparison.
**Choice B is incorrect.** There is no evidence that the two words represent contrasting attitudes (logical vs. emotional); the passage presents a likeness, not an opposition of attitudes.
**Choice C is incorrect.** The lines do not discuss reactions or outcomes the speaker hopes for or fears; they describe appearance and qualities, not responses to a decision.
**Choice D is incorrect.** The underlined items are not given as examples of a change; they function as the two terms in a simile (literal box and figurative heart), not as before-and-after instances of transformation.
**Faster approach:** Spot the simile marker ("Like") and identify the two nouns it connects; the correct choice will treat them as the literal and figurative terms being compared.'),
  ('c6d99ba9-aeb8-5e21-8691-575db7570efd', 3, null, '**Choice D is correct.** The passage begins with a general statement that applies to all baleen whales (how they feed using baleen plates) and then uses the humpback and fin whales as specific examples to show a relevant difference (their sizes and how much krill they consume). This structure is a general characteristic followed by an illustrative difference related to that characteristic.
**Choice A is incorrect.** The passage first states a feature shared by baleen whales, then gives a difference between humpback and fin whales; it does not first draw a distinction and then present a common feature.
**Choice B is incorrect.** The passage does describe whales and krill but does not discuss population changes or consequences of those changes.
**Choice C is incorrect.** The passage does not present a feature unique to the humpback or claim the fin whale lacks it; both are described in relation to the shared baleen-feeding trait.
**Faster approach:** Identify the topic sentence (often the first sentence) to see if it states a general idea, then note whether subsequent sentences provide illustrative examples or contrasts; that pattern quickly distinguishes choices about general-to-specific vs. specific-to-general structure.'),
  ('d3e1d4e1-39c7-53f3-85ca-0e7ad30b9cb5', 2, null, '**Choice C is correct.** The underlined clause gives specific details about how non–Indigenous-led museums behave—what they anticipate (mainly non‑Indigenous audiences) and what strategies they use (Euro‑centric exhibit design). That additional information elaborates on the general contrasting statement that precedes it.
**Choice A is incorrect.** The clause does not define a term from earlier in the sentence; it supplies examples of behavior rather than a definition.
**Choice B is incorrect.** The clause does not respond to or rebut a potential criticism; it simply describes how such museums tend to operate.
**Choice D is incorrect.** The clause does not acknowledge an exception to the earlier principle; instead it expands on the principle by providing specific characteristics.
**Faster approach:** Identify whether the underlined text supplies a definition, a rebuttal, an elaboration (specifics/examples), or an exception; matching wording like “tend to” and concrete details signals elaboration, so choose that answer quickly.'),
  ('5cea636d-84e9-5c36-a40e-ce3829c7918c', 2, null, '**Choice C is correct.** Both texts state that cooperation between tribal groups and government agencies improves relationships and leads to better conservation outcomes: Text 1 says the collaborative approach “has helped build trust” and will “likely improve the quality of any joint conservation projects,” and Text 2 says incorporating traditional knowledge “has helped build positive relationships” and “tends to lead to better conservation outcomes.” Together these lines support that conservation projects benefit from such collaboration.
**Choice A is incorrect.** Neither text claims collaboration reduces temperature increases; both link collaboration to better conservation outcomes, not to changing climate trends.
**Choice B is incorrect.** Text 1 says northern wild rice will fare worse than the crow, which would not imply conservation focused on rice is more effective; Text 2 gives no species comparison.
**Choice D is incorrect.** Text 1 notes rice will fare worse, but neither text asserts that focusing on rice is more important than focusing on the crow.
**Faster approach:** Look for the single idea both passages explicitly state (collaboration improves outcomes); eliminate choices that introduce new claims about climate causes or prioritizing species.'),
  ('fe66ef32-ac24-5b73-a94f-88cfba270ac2', 2, null, '**Choice C is correct.** The narrator contrasts the river in Paris with the river beyond the viaduct: in the city the river is blocked and constrained by the viaduct, whereas beyond the arches the Seine "suddenly" spreads out and "became all at once the peaceful river which flows through the plains." This language characterizes the Seine as more confined in Paris and more open/peaceful in the countryside.
**Choice A is incorrect.** The text describes the change as sudden—"suddenly spreading out"—not gradual, so "gradually cleared" misstates the passage.
**Choice B is incorrect.** Nothing in the passage says the current intensifies under the viaduct; the emphasis is on confinement versus peaceful openness, not increased force.
**Choice D is incorrect.** The passage praises the river’s peacefulness after Paris but does not claim the Seine’s loveliness is surpassed only by Paris; that comparative claim is unsupported.
**Faster approach:** Spot contrast words (e.g., "suddenly," "became," "peaceful") and eliminate choices that contradict those specific descriptors.'),
  ('b7222dd4-7cb4-5b77-b34d-41b0466b4546', 2, null, '**Choice C is correct.** The hypothesis predicts that in low-visibility conditions intermediate-headed fish will detect (and therefore avoid) obstructions that create large vortices more often than wide-headed fish. If a study finds that wide-headed Synodontis macropunctata bumped into obstructions more often than the intermediate-headed dusky smooth-hound did, that directly shows intermediate-headed fish detecting and avoiding obstructions more effectively, which supports the hypothesis.
**Choice A is incorrect.** While it reports that a wide-headed species bumped into many obstructions, it gives no comparison to intermediate-headed fish, so it does not directly support the claim that intermediate-headed fish are more likely to detect obstructions.
**Choice B is incorrect.** Variation among specimens of the intermediate-headed species does not compare intermediate- and wide-headed fish and therefore does not test the hypothesis.
**Choice D is incorrect.** Finding equal bumping rates contradicts or fails to support the hypothesis that intermediate-headed fish are more likely to detect obstructions than wide-headed fish.
**Faster approach:** Look for an answer that gives a direct comparison between intermediate- and wide-headed fish under the specified conditions; the choice showing intermediate fish avoiding obstructions more often is the correct support.'),
  ('a78b6793-7480-5d39-b1b6-fb55f64eafcf', 1, null, '**Choice B is correct.** The underlined claim says that the breadth of disciplines in Reckoning and Resilience sets it apart; showing that three named artists work in three different media (painter, photographer, sculptor) directly demonstrates that the exhibition spans multiple artistic disciplines and therefore supports the claim.
**Choice A is incorrect.** Whether works are owned by the museum concerns provenance or ownership, not the variety of artistic disciplines, so it does not support the claim about breadth of disciplines.
**Choice C is incorrect.** That the museum has a varied collection generally (including works by artists outside North Carolina) does not establish that Reckoning itself includes a broad range of disciplines; it addresses the collection, not the specific exhibition.
**Choice D is incorrect.** Stating that Across County Lines featured only North Carolina photographers would support the point that a past exhibition was discipline-specific, but the passage already identifies Across County Lines as a photography exhibition; D does not directly show that Reckoning is broader in disciplines the way B does.
**Faster approach:** Identify the claim’s focus (breadth of disciplines) and pick the choice that directly gives evidence of multiple distinct media rather than unrelated facts about ownership, collection scope, or redundancy with passage wording.'),
  ('6cf41d8e-9903-5b51-944c-f8bbc5e75182', 2, null, '**Choice C is correct.** The student claims ego-based (speaker-relative) conceptualizations of time are universal; if Yupno speakers consistently point uphill for future events regardless of the direction they face, they are using a geocentric (environment-anchored) frame, not an ego-based frame. This directly contradicts the universality claim by providing a clear counterexample.
**Choice A is incorrect.** Pointing in opposite directions for past vs. future is a classic ego-based pattern (relative to the speaker), so this finding would support, not weaken, the student’s claim.
**Choice B is incorrect.** Sharing some temporal grammatical structures with Spanish does not show that conceptualization must be ego-based; it doesn’t contradict universality and could even be consistent with ego-based mapping.
**Choice D is incorrect.** A difference in gesture frequency does not address whether gestures encode time relative to the speaker; fewer gestures doesn’t demonstrate a non-ego-based spatial mapping.
**Faster approach:** To refute a universality claim, look for a direct counterexample—evidence that a culture uses a non-ego-based (e.g., geocentric) temporal mapping such as fixed environmental directions.'),
  ('60121067-5439-54c6-accf-aea1ab5f2153', 3, null, '**Choice D is correct.** The passage hypothesizes that a New York–specific Spanish dialect has developed partly because of interaction with English, and it cites research showing that younger speakers of nonmajority languages are more likely than older speakers to borrow from a region’s majority language. Putting those two points together, if a New York Spanish dialect arises through borrowing from English, younger Spanish speakers should be more likely than older speakers in the same neighborhood to use that dialect.
**Choice A is incorrect.** The passage gives no basis for comparing neighborhoods with many languages to neighborhoods where Spanish and English predominate; it only links age and borrowing behavior, not neighborhood language diversity.
**Choice B is incorrect.** The passage does not claim that numbers of languages or dialects will increase over time; it makes a specific claim about dialect formation linked to English interaction and age-related borrowing patterns.
**Choice C is incorrect.** The passage says younger speakers borrow more from the majority language (English), not from other nonmajority languages, so this choice contradicts the passage’s evidence.
**Faster approach:** Combine the hypothesis with the cited research by matching the agent and direction (younger vs. older speakers borrowing from the majority language) to pick the answer that directly compares younger and older speakers’ likelihood of using the new dialect.'),
  ('c118946f-fe05-5e58-a0fc-abb8b29fc189', 1, null, '**Choice B is correct.** The passage states that no source before 1155 includes references to the Round Table and that both the Roman de Brut (1155) and Malory’s Le Morte d’Arthur do include such references. Because Preiddeu Annwfn (circa 900) lacks any Round Table material, Malory could not have relied on it as a source for his Round Table information.
**Choice A is incorrect.** The passage gives no basis for claiming that Malory’s work is more historically accurate than Geoffrey’s; the timing of the Mabinogion is irrelevant to that unsupported conclusion.
**Choice C is incorrect.** While the first clause (Geoffrey was unaware of Round Table stories) might follow, the second clause contradicts the passage: it says no pre-1155 sources include the Round Table, so works containing such stories were not available to Geoffrey.
**Choice D is incorrect.** The passage indicates Geoffrey’s History predates references to the Round Table that appear in the Roman de Brut, so there is no basis for claiming greater similarity to the Mabinogion than to Wace’s work.
**Faster approach:** Use the timeline in the passage—identify which works predate the Round Table reference (none do) and eliminate any answer that implies an earlier source could have supplied that detail.'),
  ('3ce54a6d-2851-541e-9b2e-496f60ed74c6', 0, null, '**Choice A is correct.** The passage identifies the problem as coins having only $74.2%$ silver when $80%$ was the informal threshold for trade. If Abd’astart I kept the same absolute amount of silver per coin but decreased each coin’s total weight, the fraction of silver would rise above $80%$ (because silver mass/total mass would increase), making the coins acceptable to traders and thus relieving the confidence crisis without needing new silver sources.
**Choice B is incorrect.** Simply proclaiming a higher suitability threshold does not change the metal content of existing coins; raising the standard above $80%$ would also make acceptance stricter rather than immediately restoring confidence.
**Choice C is incorrect.** Funding copper mining would increase copper availability and likely increase copper in coins, which would further lower the silver percentage and worsen confidence.
**Choice D is incorrect.** Minting heavier coins with the same silver-to-copper proportion leaves the silver percentage at about $74.2%$, so traders would still find them unsuitable.
**Faster approach:** When a passage gives a numeric shortfall (here, silver below $80%$), eliminate answers that do not increase the relevant ratio; choose the option that directly raises the silver proportion (add silver, remove other metals, or reduce total weight).'),
  ('124b0a7a-addb-5bd4-9e91-b1dd040f3f58', 1, null, '**Choice B is correct.** The sentence links two independent clauses: "the guide soon grew in scope and influence" and "its modest French eateries were replaced with..." Joining independent clauses with a coordinating conjunction requires a comma before that conjunction; because the word "and" already appears between "scope" and "influence," the comma and coordinating conjunction must come after "influence," which is exactly what "influence, and" provides. The resulting phrasing—"grew in scope and influence, and its modest... were replaced"—correctly and clearly connects the two clauses.
**Choice A is incorrect.** Omitting punctuation yields "grew in scope and influence its modest...," which makes the sentence run together and misassigns "influence" to modify "its modest..." rather than serving as part of the first clause.
**Choice C is incorrect.** A comma alone ("influence,") produces a comma splice: two independent clauses joined only by a comma without a coordinating conjunction.
**Choice D is incorrect.** "influence and" produces an awkward and ungrammatical string ("grew in scope and influence and its...") that fails to mark the boundary between the two independent clauses.
**Faster approach:** Identify the two independent clauses and ensure they’re joined with a comma plus a coordinating conjunction; pick the choice that supplies ", and" at the clause boundary.'),
  ('f1ba05c7-dd0e-5037-a56d-027ec8fd08fa', 0, null, '**Choice A is correct.** The subject of the clause is the plural noun phrase "Many (of whom)," so the verb must be plural and match simple present tense to indicate a general activity: "study." The sentence then reads smoothly: "Many of whom, like neuroscience and biophysics expert Elba Serrano, study this mechanism..." which conforms to Standard English and completes the sentence.
**Choice B is incorrect.** "Has studied" is singular present perfect and does not agree with the plural subject "Many."
**Choice C is incorrect.** "Studies" is third-person singular present and therefore disagrees with the plural subject "Many."
**Choice D is incorrect.** "Is studying" is singular progressive; the correct plural progressive would be "are studying," so this form is ungrammatical here.
**Faster approach:** Check subject-number agreement: match a plural subject like "many" with a plural verb ("study").'),
  ('3246ca31-1250-554f-b0ff-eb9db0b6f97f', 3, null, '**Choice D is correct.** The phrase "the hit ''Oh What a Day'' by the Dells" contains a restrictive noun phrase: the quoted title identifies which hit is being referred to, so no additional punctuation is needed between "hit" and the quoted title. In Standard English, restrictive appositives that directly name or specify the noun are not set off by commas or other punctuation; therefore the sentence should read: "...you would have heard the hit "Oh What a Day" by the Dells."
**Choice A is incorrect.** A colon is used to introduce a list, an explanation, or a quotation of a full sentence; it is not required here to name a specific song title immediately following a noun.
**Choice B is incorrect.** A comma would treat the title as a nonrestrictive appositive (extra information), which changes the meaning and is not the conventional punctuation when the title is essential to identify the hit.
**Choice C is incorrect.** A semicolon separates independent clauses or complex list items; it is never used directly between a noun and a following title.
**Faster approach:** Identify whether the phrase after the noun is restrictive (essential) or nonrestrictive (extra). If it’s essential identification (a title naming which item), use no punctuation; eliminate
colon/semicolon immediately.'),
  ('bd41b3b3-46dd-584d-844b-302abbff78dd', 0, null, '**Choice A is correct.** The sentence links two examples of topics researchers study: "Lucia Macchia ... studies socioeconomic inequality" and "other researchers investigate areas such as organizational behavior and personal finance." These are two independent but related elements, so a comma after "inequality" sets off the transitional phrase "for instance" that introduces the second example; the clause that follows is a continuation, so the sentence should end with a semicolon to join the two related independent structures correctly and a closing punctuation mark (the provided choice A shows the comma before "for instance" and the semicolon after it, which fits the required pause and connection). The sequence ", for instance;" correctly signals that what follows is an illustrative list connected to the preceding clause.
**Choice B is incorrect.** A semicolon before "for instance" and a comma after it would create an unnecessary break: the semicolon should join two independent clauses, but placing it before the transitional phrase and then a comma after disrupts the natural flow and punctuation rules for introducing an example.
**Choice C is incorrect.** A comma both before and after "for instance" would set the phrase off parenthetically, which could work only if the sentence continued as a single independent clause; but here the clause after "for instance" is a separate independent clause that requires stronger punctuation than an internal comma to join properly.
**Choice D is incorrect.** Omitting the comma before "for instance" fails to set off the transitional phrase and makes the sentence read awkwardly; without punctuation it does not clearly indicate that the following clause is an illustrative example connected to the first clause.
**Faster approach:** Recognize that "for instance" is a transitional phrase introducing an example; when it connects two related independent ideas, use punctuation that both sets off the phrase and properly links the clauses—look for the choice that places a comma before the phrase and stronger punctuation (semicolon) to join the clauses.'),
  ('dc5274e7-424a-5a80-b8db-dcf7314c82f1', 1, null, '**Choice B is correct.** The sentence uses a conjunctive adverb ("however") to link two independent clauses that share the same subject ("The book wasn’t written solely by Kittredge" and "other authors ... also contributed essays"). The correct punctuation for a conjunctive adverb joining two independent clauses is a semicolon before it and a comma after it: "Kittredge; however, other authors..." This preserves the close connection between the clauses without creating a comma splice or two sentence fragments.
**Choice A is incorrect.** A comma before "however" creates a comma splice when joining two independent clauses: "Kittredge, however other authors..." would leave the second clause improperly joined and also lacks the necessary comma after "however."
**Choice C is incorrect.** A period before "However" would create two separate sentences. While grammatically possible, it changes the intended flow; more importantly, the clause that follows ("other authors ... also contributed essays") is a complete independent clause, so starting a new sentence with "However" is acceptable but not the best punctuation given the sentence’s original structure. The College Board expects the semicolon+comma construction here.
**Choice D is incorrect.** A comma after "Kittredge" (with a comma but no punctuation before "however") is incorrect because it produces a comma splice and still omits the comma that must follow "however" when it interrupts the sentence: it reads "Kittredge, however other..." which is ungrammatical.
**Faster approach:** For any sentence joining two independent clauses with a conjunctive adverb (however, therefore, moreover, consequently), use a semicolon before the conjunctive adverb and a comma after it—always check for "independent clause ; however, independent clause."'),
  ('b5bee7dc-e9b9-588a-a5f4-6c398ab0da07', 2, null, '**Choice C is correct.** The present-participial verb "suggesting" creates a modifier that links the noun "This hypothesis" to the content of the clause that follows: the hypothesis (which suggests that certain trees survived) cannot stand. Read this way, the sentence means that the hypothesis — which makes the claim about survival — cannot stand unless other explanations are ruled out, which matches the intended meaning.
**Choice A is incorrect.** "Suggests" would make the main verb of the sentence, producing an awkward and ungrammatical reading in which the hypothesis itself "suggests that ... cannot stand."
**Choice B is incorrect.** "Suggested" has the same structural problem as A but in past tense, creating a main-verb construction that does not convey the intended modifier relationship.
**Choice D is incorrect.** "Has suggested" likewise makes the clause a main-verb statement about what the hypothesis has done, rather than a modifier describing the hypothesis; it therefore fails to express the intended meaning.
**Faster approach:** Recognize whether the blank should form a noun modifier (a participle) or a main verb; if the phrase must describe the hypothesis (not state what it does), choose a participial form like "suggesting."'),
  ('0b669e33-7b1f-5d41-9b1f-7bd5f85f6616', 2, null, '**Choice C is correct.** The sentence before the blank asserts that Saethre "succeeds in creating a whimsical yet perplexing experience." The following clause—"when visitors set foot... they are both dazzled and confused"—provides specific evidence that supports and elaborates that assertion. "Indeed," signals confirmation or reinforcement, so "Indeed, when visitors..." smoothly links the general claim to the illustrative example.
**Choice A is incorrect.** "Second," introduces an ordinal (a second point) and would require a preceding "First" or numbered sequence; no such sequence exists here.
**Choice B is incorrect.** "Nevertheless," indicates contrast or concession; the sentence that follows does not contradict the preceding claim but rather reinforces it, so a contrast marker is inappropriate.
**Choice D is incorrect.** "Instead," signals substitution or an alternative and would create a mismatch with the intended confirmatory/example relationship between the two sentences.
**Faster approach:** Identify whether the following clause reinforces, contrasts, or introduces an example; then choose a transition that matches (e.g., "Indeed" for reinforcement, "Nevertheless" for contrast, ordinal words only for numbered lists).'),
  ('4da75bfc-abb4-5d95-ba4d-8bf763ae9717', 3, null, '**Choice D is correct.** The preceding clause explains a shift in purpose for modern via ferratas (they''re "rarely designed to simply reach a summit"). The next sentence states what modern routes do instead, so a transition indicating frequency or prevalence—"More often,"—creates a logical continuation: instead of being utilitarian, new routes favor recreation.
**Choice A is incorrect.** "Nonetheless" signals a contrast that would conflict with the previous idea; the second sentence does not contradict the first, it elaborates on what modern routes do instead.
**Choice B is incorrect.** "On the other hand" also implies a contrasting alternative and would make the relationship between the sentences unclear.
**Choice C is incorrect.** "Additionally" suggests an extra, coexisting point rather than indicating what is more commonly done; it weakens the intended shift from utility to recreation.
**Faster approach:** Look for the logical relationship between sentences first—contrast, addition, or consequence—and choose the transition that signals that relationship (here, a frequent alternative: "More often").'),
  ('b8b0a82e-3ec9-5d28-a1d4-7fd1d49c1957', 1, null, '**Choice B is correct.** It directly uses Heller’s praising quotation to rebut the claim that slow TV is boring and ties that praise to a concrete example from the notes (viewers watching reindeer migrations in real time), which shows how the quotation undermines the “boring” characterization.
**Choice A is incorrect.** It merely presents both the praise and the criticism side by side rather than using the praise to refute the claim that slow TV is boring.
**Choice C is incorrect.** It uses the phrase “the world’s most boring television” to support the claim rather than to refute it, so it does not accomplish the student’s goal.
**Choice D is incorrect.** Although it applies Heller’s quotation to Reinflytting, it lacks the explicit contrast needed to refute the claim that slow TV is boring and is less forceful than B.
**Faster approach:** For rhetorical-synthesis questions, choose the answer that both cites the relevant quotation and links it to a specific example from the notes to directly counter the opposing claim.'),
  ('39396f9b-6825-543e-888a-3da3a2f3dec3', 1, null, '**Choice B is correct.** It directly states the specific number of chromosomes for the fennec fox—"sixty-four chromosomes"—which exactly accomplishes the student’s goal of specifying how many chromosomes the fennec fox has, using the note that lists that number.
**Choice A is incorrect.** Although it compares the fennec fox to the red fox, it does not give the exact number of chromosomes for the fennec fox; it only indicates a relative difference.
**Choice C is incorrect.** It describes the function of chromosomes and genes, not the number of
chromosomes the fennec fox has, so it does not answer the student’s specific question.
**Choice D is incorrect.** It gives the number of chromosomes for the red fox, not for the fennec fox, so it fails to specify the fennec fox’s chromosome count.
**Faster approach:** Look for the answer choice that repeats the exact numeric fact requested; when a question asks for a specific value, choose the choice that states that value directly.'),
  ('1951779b-6740-5bbd-8a0d-09c89b265e64', 3, null, '**Choice D is correct.** The student’s notes explicitly state that a report on 2021 London Fashion Week noted the popularity of “a stirring ocean blue shade that was cool in tone and bright in intensity.” Choice D restates that information directly, saying designer collections featured a cool, bright shade of stirring ocean blue, which matches the passage wording.
**Choice A is incorrect.** Although true that both shades appear in consultants’ reports, this choice does not specifically describe the color popular at 2021 London Fashion Week; it speaks generally about reports.
**Choice B is incorrect.** This choice restates a general function of color consultants but does not describe the 2021 London Fashion Week color.
**Choice C is incorrect.** While the 2021 shade differs from the 2018 petal pink, this choice emphasizes contrast (“a departure”) rather than accurately and directly describing the 2021 color as cool and bright.
**Faster approach:** Look for the answer choice that repeats the exact descriptive words from the passage (here, "stirring ocean blue," "cool," "bright") to match the source precisely.'),
  ('1be64620-27e5-5523-bbbb-783e31c344c6', 0, null, '**Choice A is correct.** It places Einstein’s position within the broader historical moment by referring to the “dawn of quantum theory” (the notes identify the emerging field of quantum theory) and accurately contrasts Einstein’s belief in the independent reality of subatomic entities with Bohr’s opposing
interpretation, which the notes say “remains the most widely accepted theory.” This choice synthesizes relevant facts from the notes into a clear historical context.
**Choice B is incorrect.** Although accurate that Einstein opposed Bohr and that prominent scientists attended the conference, it merely restates facts without situating Einstein’s argument within a broader historical context.
**Choice C is incorrect.** It mentions the debate and Bohr’s lasting influence but misfocuses on Bohr rather than placing Einstein’s argument in historical context as requested.
**Choice D is incorrect.** It reverses the positions: the notes say Bohr argued for probabilistic realities and Einstein argued for independent reality, so D is factually incorrect.
**Faster approach:** Look for the option that both names Einstein’s specific claim and links it to a historical framing (e.g., “dawn of quantum theory” or later acceptance) and eliminate choices that merely restate facts or reverse positions.'),
  ('e60f59f9-9e0a-5601-9c9b-f16fd684a336', 2, null, '**Choice C is correct.** The notes state that "minerals with larger numbers are harder than minerals with smaller numbers and can leave visible scratches on them." That rule applies generally: any mineral with Mohs number 8 can scratch any mineral with Mohs number 5, so the claim about an 8 scratching a 5 follows directly from the given information.
**Choice A is incorrect.** Although the ordering topaz (8) > apatite (5) > calcite (3) is true, it restates specific data rather than making a generalizable rule about minerals.
**Choice B is incorrect.** While topaz can scratch calcite, the phrase "which is why" implies a causal explanation beyond the simple comparative rule; it restates an instance rather than presenting the general principle.
**Choice D is incorrect.** The Mohs scale can indeed order those three minerals, but this choice is narrowly about those examples and not the broader generalization about all minerals of different Mohs numbers.
**Faster approach:** Apply the general rule from the notes—"larger Mohs number can scratch smaller"—to see which answer states a general relationship rather than merely listing examples.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

