insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('54f87646-d017-5f98-b313-e3ce17f9ba43', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'The equation gives the speed $s$, in miles per hour, of a certain car $t$ seconds after it began to accelerate. What is the speed, in miles per hour, of the car $5$ seconds after it began to accelerate?
$s = 50 + 4t$', '["$50$", "$54$", "$55$", "$70$"]'::jsonb, 1, null),
  ('88796500-7aa8-5302-8a79-572b4b92cc2e', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'The function $f$ is defined by $f(x) = x^{2} + 15$. What is the value of $f(2)$?', '["$2$", "$15$", "$17$", "$19$"]'::jsonb, 2, null),
  ('1f2a1385-40ce-563e-83cd-cdb017659268', '2ed5c240-8f8d-5208-88e7-b99f7569d417', '$\sqrt{w} + 34 = 40$
What is the solution to the given equation?', '["$2$", "$3$", "$12$", "$36$"]'::jsonb, 3, null),
  ('6647ac22-825b-5280-a7df-9ebe0cb0bf26', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'An aquarium uses small and large tanks to temporarily hold a total of $37$ fish. Each small tank holds $1$ fish, and each large tank holds $2$ fish. Which equation represents this situation, where $s$ is the number of small tanks and $b$ is the number of large tanks the aquarium uses?', '["$s + 2b = 37$", "$s + b = 37$", "$2s + b = 37$", "$2s + 2b = 37$"]'::jsonb, 4, null),
  ('0e8019d9-e7bc-5a51-b5f8-bd403872889d', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'The growth of the number of bacteria in a certain population is modeled by a function that increases exponentially over time. Which of the following could describe how the number of bacteria in the population changes each hour?', '["Each hour, the number of bacteria in the population is $1,600$ greater than was the previous hour.", "Each hour, the number of bacteria in the population is $16%$ greater than it was the previous hour.", "Each hour, the number of bacteria in the population is $1,600$ less than it was the previous hour.", "Each hour, the number of bacteria in the population is $16%$ less than it was the previous hour."]'::jsonb, 5, null),
  ('39c35821-f2a8-57ca-a6e7-bcca03e3e846', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'To win a game show, a contestant needs to score at least $100$ total points from two rounds. Correct responses in the first round are worth $2$ points each, and correct responses in the second round are worth $5$ points each. Which inequality models this situation, where $f$ is the number of correct responses in the first round and $s$ is the number of correct responses in the second round?', '["$f + s \\le 100$", "$2f + 5s \\ge 100$", "$5f + s \\ge 100$", "$5f + 2s \\le 100$"]'::jsonb, 6, null),
  ('9c2e072e-ba00-510d-a78f-acb21a225781', '2ed5c240-8f8d-5208-88e7-b99f7569d417', '$W(x) = 2x + 60$
The function $W$ gives the total time, in minutes, it takes for a gardener to water $x$ plants and mow the grass. According to the function, how many minutes does it take the gardener to mow the grass?', '[]'::jsonb, 7, null),
  ('ed86787e-ca02-532d-9027-4043b5a4803f', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'Triangles $JKL$ and $PQR$ are congruent, where $J$ corresponds to $P$, and $K$ corresponds to $Q$. The measure of angle $J$ is $45°$, the measure of angle $K$ is $10°$, and the measure of angle $L$ is $125°$. What is the measure, in degrees, of angle $P$? (Disregard the degree symbol when entering your answer.)', '[]'::jsonb, 8, null),
  ('e3964382-08a5-5224-8ef7-6e310b8bd157', '2ed5c240-8f8d-5208-88e7-b99f7569d417', '$y = 5x + 10$
$y = 5x - 2$
At how many points do the graphs of the given equations intersect in the $xy$-plane?', '["Zero", "Exactly one", "Exactly two", "Infinitely many"]'::jsonb, 9, null),
  ('6d33cff2-23f0-59b7-8242-33ec4e1c708a', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'The table shows three values of $a$ and their corresponding values of $y$ for the equation $y = 4(2)^{x} + 5$. In the table, $a$ is a constant. What is the value of $a$?', '["$69$", "$37$", "$32$", "$29$"]'::jsonb, 10, '| $x$ | $y$ |
| $1$ | $13$ |
| $2$ | $21$ |
| $3$ | $a$ |'),
  ('497e4d65-7398-5afe-9847-dd0ca929af0f', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'The number of bacteria in a liquid medium doubles every day. There are $72,000$ bacteria in the liquid medium at the start of an observation. Which of the following represents the number of bacteria, $y$, in the liquid medium $t$ days after the start of the observation?', '["$y = \\frac{1}{2}(72,000)^{t}$", "$y = 2(72,000)^{t}$", "$y = 72,000(\\frac{1}{2})^{t}$", "$y = 72,000(2)^{t}$"]'::jsonb, 11, null),
  ('8b531146-e459-5d19-9dc7-7d6b096a1f38', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'A rectangle has a width of $n$ yards and a length of $(n + 5)$ yards. If the rectangle has an area of $204$ square yards, what is the value of $n$?', '[]'::jsonb, 12, null),
  ('d6518da9-7ef1-5a8e-864b-b476da4b8675', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'The function $f$ is defined by
$f(x) = 9\frac{x}{8} + 11$
For what value of $x$ is $f(x)$ equal to $38$?', '[]'::jsonb, 13, null),
  ('2f2c1cf2-6778-5b4b-9f23-e653408908b7', '2ed5c240-8f8d-5208-88e7-b99f7569d417', '$f(x) = x^{2} - 42x + 80$
The function $f$ is defined by the given equation. Which of the following equivalent forms of the equation displays the zeros of the function as constants or coefficients?', '["$f(x) = x^{2} - 5x - 37x + 80$", "$f(x) = (x - 2)(x - 40)$", "$f(x) = x(x - 42) + 80$", "$f(x) = (x - 21)^{2} - 361$"]'::jsonb, 14, null),
  ('5773e888-fa67-597b-b38f-baa6502d18cd', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'For the linear function $g$, the table shows four values of $x$ and their corresponding values of $g(x)$. The function can be written as $g(x) = mx + b$, where $m$ and $b$ are constants. What is the value of $b$?', '[]'::jsonb, 15, '| x | g(x) |
| 1 | 46 |
| 2 | 43 |
| 3 | 40 |
| 4 | 37 |'),
  ('7f0b607d-ef02-5b5f-9847-6a949537c0a8', '2ed5c240-8f8d-5208-88e7-b99f7569d417', '$x + 5y = 5$
$x - 5y = 3$
The solution to the given system of equations is $(x,y)$. What is the value of $x$?', '["0.8", "4", "5", "8"]'::jsonb, 16, null),
  ('56e637a3-84fc-50af-bb0e-ad05baae2662', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'If $\cos A = 0.55$, what is the value of $\sin C$?', '["$0.12$", "$0.45$", "$0.55$", "$0.84$"]'::jsonb, 17, '![figure](/q/aug24/002.webp)'),
  ('599900a7-e6d6-5689-9373-5e28bad20c1b', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'If a customer order is selected at random, what is the probability of selecting an order with sprinkles, given the flavor of ice cream is vanilla?', '["$0.08$", "$0.13$", "$0.25$", "$0.40$"]'::jsonb, 18, 'The table gives the distribution of flavor and type of topping for customer orders at an ice cream shop.

| Flavor of ice cream | Type of topping |  |
| **Sprinkles** | **No Sprinkles** |  |
| Chocolate | 60 | 30 |
| Vanilla | 20 | 30 |
| Twist | 80 | 20 |'),
  ('c4b97001-c095-594f-9695-c076f23a7d31', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'In the given equation, $r$ is a positive integer. If the given equation has exactly one solution, what CANNOT be the value of $r$?
$x(r - 7) + 3 = 19x + 25$', '["$3$", "$7$", "$22$", "$26$"]'::jsonb, 19, null),
  ('6ec80564-288c-5a86-857f-46b4a767a464', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'A real estate company offers a series of three webinars. $2,000$ people attended the first webinar, $65%$ of the people who attended the first webinar attended the second webinar, and $44%$ of the people who attended both the first and second webinar attended the third webinar. Of those who attended the first but did not attend the second webinar, $31%$ attended the third webinar. How many people attended both the first and third webinars but did not attend the second webinar?', '[]'::jsonb, 20, null),
  ('85da7257-2a94-5247-a95a-5c7da1ea6d08', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'In the $xy$-plane, circle $M$ is the graph of the equation $(x + 6a)^{2} + (y - 38a)^{2} = 36a^{2}$ where $a$ is a positive constant. Circle $V$ is obtained by shifting circle $M 12a$ units to the right. Which equation represents circle $V$?', '["$(x + 18a)^{2} + (y - 38a)^{2} = 36a^{2}$", "$(x + 6a)^{2} + (y - 50a)^{2} = 36a^{2}$", "$(x + 6a)^{2} + (y - 26a)^{2} = 36a^{2}$", "$(x - 6a)^{2} + (y - 38a)^{2} = 36a^{2}$"]'::jsonb, 21, null),
  ('d97e4baa-ed8f-57e2-8150-04cebf009d38', '2ed5c240-8f8d-5208-88e7-b99f7569d417', 'The dot plot shows the distribution of capacity for a set of capacitors, set A, which a researcher used for a certain experiment. For another experiment, the researcher used a different set of capacitors, set B. Set B has the same number of capacitors as set A but the capacity of each capacitor of set B is $14$ microfarads ($μ$ F) greater than the capacity of each respective capacitor in set A. Which of the following is true about the capacities of the capacitors in set B?', '["The mean capacity is $10μ$ F, and the range of capacities is $12μ$ F.", "The mean capacity is $10μ$ F, and the range of capacities is $26μ$ F.", "The mean capacity is $24μ$ F, and the range of capacities is $12μ$ F.", "The mean capacity is $24μ$ F, and the range of capacities is $26μ$ F."]'::jsonb, 22, '![figure](/q/aug24/003.webp)')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('54f87646-d017-5f98-b313-e3ce17f9ba43', 3, null, '**Choice D is correct.** The equation gives speed as $s = 50 + 4t$. Substitute $t = 5$ to get $s = 50 + 4(5) = 50 +$ $20 = 70$, so the speed is $70$ miles per hour.
**Choice A is incorrect.** That choice gives $50$, which is the speed at $t = 0$, not at $t = 5$.
**Choice B is incorrect.** That choice gives $54$, which would correspond to $t = 1$ if $s = 50 + 4t$; it does not match $t = 5$.
**Choice C is incorrect.** That choice gives $55$, which would be $50 + 5$, not $50 + 4(5)$; it does not follow from the given formula for $t = 5$.
**Faster approach:** Direct substitution — plug $t = 5$ into $s = 50 + 4t$ to compute $s = 50 + 20 = 70$. This substitution method works for any linear expression of this form.'),
  ('88796500-7aa8-5302-8a79-572b4b92cc2e', 3, null, '**Choice D is correct.** Substitute $x = 2$ into $f(x) = x^{2} + 15$ to get $f(2) = 2^{2} + 15 = 4 + 15 = 19$, so the value of $f(2)$ is $19$.
**Choice A is incorrect.** The value $2$ would be the input, not the output; substituting $x = 2$ does not yield $2$.
**Choice B is incorrect.** The constant term $15$ is part of the expression, but adding $2^{2}$ changes the output to $19$ , so $15$ is not the result of $f(2)$.
**Choice C is incorrect.** $17$ would be $15 + 2$, but $f(2)$ requires $15 + 2^{2} = 15 + 4 = 19$, so $17$ is not correct.
**Faster approach:** Direct substitution—plug the given input into the expression and evaluate ($2^{2} + 15$)—is the quickest reliable method for any problem asking for $f$ of a number.'),
  ('1f2a1385-40ce-563e-83cd-cdb017659268', 3, null, '**Choice D is correct.** Subtract 34 from both sides to get $\sqrt{w} = 6$. Squaring both sides gives $w = 36$. Because $\sqrt{w}$ denotes the principal (nonnegative) square root, $w = 36$ is valid and satisfies the original equation: $\sqrt{36} + 34 = 6 + 34 = 40$.
**Choice A is incorrect.** If $w = 2$, then $\sqrt{2} + 34 \approx 1.414 + 34 \ne 40$, so it does not satisfy the equation.
**Choice B is incorrect.** If $w = 3$, then $\sqrt{3} + 34 \approx 1.732 + 34 \ne 40$, so it is not a solution.
**Choice C is incorrect.** If $w = 12$, then $\sqrt{12} + 34 \approx 3.464 + 34 \ne 40$, so this choice is also not a solution.
**Faster approach:** Isolate the square root immediately ($\sqrt{w} = 40 - 34 = 6$) and square to find $w = 6^{2} = 36$. This approach (isolate then square) is the direct method for equations involving a single square-root expression.'),
  ('6647ac22-825b-5280-a7df-9ebe0cb0bf26', 0, null, '**Choice A is correct.** Each small tank holds 1 fish and each large tank holds 2 fish, so the total number of fish is $1 \cdot s + 2 \cdot b$. Setting that equal to 37 gives $s + 2b = 37$, which matches choice A.
**Choice B is incorrect.** $s + b = 37$ would mean both small and large tanks each hold exactly 1 fish, so it undercounts the fish from large tanks (which hold 2 each).
**Choice C is incorrect.** $2s + b = 37$ treats small tanks as holding 2 fish each and large tanks as holding 1 each, which reverses the given capacities.
**Choice D is incorrect.** $2s + 2b = 37$ counts 2 fish per tank for both types, so it overcounts the small tanks (which hold only 1 fish each) and would require the total 37 to be even, which it is not.
**Faster approach:** Translate directly: "small = 1 fish" gives $1 \cdot s$, "large = 2 fish" gives $2 \cdot b$, then add to equal total; this yields $s + 2b = 37$ every time for this skill.'),
  ('0e8019d9-e7bc-5a51-b5f8-bd403872889d', 1, null, '**Choice B is correct.** Exponential growth means the population is multiplied by a constant factor each hour. Saying the population is "16% greater" each hour means the new population is $1 + 0.16 = 1.16$ times the previous hour’s population, so the count is multiplied by the constant factor $1.16$ each hour, which is exponential growth.
**Choice A is incorrect.** Saying the number is 1,600 greater each hour adds a fixed amount (arithmetic/linear growth), not multiplies by a constant factor, so it is not exponential.
**Choice C is incorrect.** Being 1,600 less each hour is a constant subtraction each hour (linear decrease) and also describes decline, not exponential growth.
**Choice D is incorrect.** Being 16% less each hour means the population is multiplied by $0.84$ each hour (exponential decay), not exponential growth.
**Faster approach:** Recognize that exponential change multiplies by a constant factor; percent
increase/decrease statements indicate multiplication (use $1 \pm \text{rate}$), while fixed additions/subtractions indicate linear change.'),
  ('39c35821-f2a8-57ca-a6e7-bcca03e3e846', 1, null, '**Choice B is correct.** The total points are $2$ points per first-round correct response and $5$ points per second-round correct response, so the total score is $2f + 5s$. The contestant needs at least $100$ points, which is represented by the inequality $2f + 5s \ge 100$.
**Choice A is incorrect.** $f + s \le 100$ counts responses not points and uses the wrong direction $(\le )$ — it does not reflect point values or the "at least" requirement.
**Choice C is incorrect.** $5f + s \ge 100$ swaps the coefficients for the rounds, attributing 5 points to first-round responses and 1 point to second-round responses, which is inconsistent with the problem.
**Choice D is incorrect.** $5f + 2s \le 100$ both swaps the point values and uses $\le$ instead of $\ge$, so it misrepresents the scoring and the requirement.
**Faster approach:** Write the score as (points per first round)$\times f$ + (points per second round)$\times s$, then apply "at least 100" to get the inequality; here that yields $2f + 5s \ge 100$. This method works for any weighted-sum threshold problem.'),
  ('9c2e072e-ba00-510d-a78f-acb21a225781', null, array['60']::text[], '**The correct answer is 60.** The function $W(x) = 2x + 60$ gives the total time (watering plus mowing). The term $2x$ depends on $x$, so it represents the time that varies with the number of plants (2 minutes per plant). The constant term $60$ does not depend on $x$, so it represents the fixed amount of time required for mowing the grass, which is 60 minutes.
**Faster approach:** Recognize that in a linear expression of the form $ax + b$ for total time, the constant $b$ is the fixed time (here mowing), so read off $b = 60$ immediately.'),
  ('ed86787e-ca02-532d-9027-4043b5a4803f', null, array['45']::text[], '**The correct answer is 45.** If two triangles are congruent and vertices are listed so that $J$ corresponds to $P$, then each pair of corresponding angles are congruent. That means $\angle P$ has the same measure as $\angle J$. The problem states $\angle J$ measures $45°$, so $\angle P$ also measures $45°$.
**Faster approach:** Use the correspondence directly: congruent triangles give equal corresponding angles, so immediately copy the given measure of $\angle J$ to $\angle P$ (no computation needed).'),
  ('e3964382-08a5-5224-8ef7-6e310b8bd157', 0, null, '**Choice A is correct.** The two equations are lines with slopes $5$ and $5$, so they are parallel. Because their $y$- intercepts ($10$ and $-2$) are different, the lines are distinct parallel lines and never meet, so there are zero intersection points.
**Choice B is incorrect.** Exactly one intersection would occur if the lines had different slopes; here the slopes are equal, so they are not guaranteed to meet at a single point.
**Choice C is incorrect.** Two intersections would require the graphs to be curves that cross twice; two distinct lines can intersect at most once, so this is impossible.
**Choice D is incorrect.** Infinitely many intersections occur only if the two equations represent the same line (identical slope and intercept). Here the $y$-intercepts differ, so the lines are not the same.
**Faster approach:** Compare slopes and intercepts: equal slopes + different intercepts implies 0 intersections; equal slopes + equal intercepts implies infinitely many; different slopes implies exactly one.'),
  ('6d33cff2-23f0-59b7-8242-33ec4e1c708a', 1, null, '**Choice B is correct.** Substitute $x = 3$ into $y = 4(2)^{x} + 5$: $y = 4(2^{3}) + 5 = 4(8) + 5 = 32 + 5 = 37$, so $a = 37$.
**Choice A is incorrect.** $69$ would result from $4(2^{4}) + 5$, not from $x = 3$, so it does not match the given formula at $x = 3$.
**Choice C is incorrect.** $32$ is $4(2^{3})$ (the exponential part) but omits the $+5$ in the formula, so it is not the value of $y$.
**Choice D is incorrect.** $29$ does not come from substituting $x = 3$ into the expression $4(2)^{x} + 5$ and is not consistent with the pattern of increases in the table.
**Faster approach:** Either substitute $x = 3$ directly into $y = 4(2)^{x} + 5$, or notice the pattern: from $x = 1$ to $x =$ $2y$ increases by $8$, so the next increase (doubling the exponential part) is $16$, giving $21 + 16 = 37$.'),
  ('497e4d65-7398-5afe-9847-dd0ca929af0f', 3, null, '**Choice D is correct.** The population doubles every day, so the growth factor per day is $2$. With an initial amount (at $t = 0$) of $72,000$, the exponential-growth model is $y = 72,000 \cdot 2^{t}$, which matches Choice D.
**Choice A is incorrect.** It uses $(72,000)^{t}$ and multiplies by $\frac{1}{2}$, which does not represent doubling growth from an initial value of $72,000$.
**Choice B is incorrect.** It gives $2(72,000)^{t}$, which treats $72,000$ as the base of the exponent and multiplies by 2, not using $72,000$ as the initial amount with base 2 growth.
**Choice C is incorrect.** It uses $(\frac{1}{2})^{t}$, which models halving each day rather than doubling.
**Faster approach:** For growth that doubles each day, write initial amount times $2^{t}$: initial value $\times$ growth factor
$t$
(so always $\text{start} \cdot 2^{t}$ for doubling).'),
  ('8b531146-e459-5d19-9dc7-7d6b096a1f38', null, array['12']::text[], '**The correct answer is 12.** Let the width be $n$ and the length $n + 5$. The area is given by $n(n + 5) = 204$, so $n^{2} + 5n - 204 = 0$. Solve the quadratic using the quadratic formula: $n = \frac{-5\pm \sqrt{5^{2}-4(1)(-204)}}{2} = \frac{-5\pm \sqrt{25+816}}{2} =$ $\frac{-5\pm \sqrt{841}}{2} = \frac{-5\pm 29}{2}$. This yields $n = 12$ or $n = -17$, and since a width must be positive, $n = 12$ yards. **Faster approach:** Factor the quadratic: find two integers with product $-204$ and sum $5$ (12 and -17), so $(n +$ $17)(n - 12) = 0$, giving $n = 12$ (discard $-17$). This saves time vs. the quadratic formula.'),
  ('d6518da9-7ef1-5a8e-864b-b476da4b8675', null, array['12']::text[], '**The correct answer is 12.** Start with $f(x) = 9^{x/8} + 11$ and set it equal to 38: $9^{x/8} + 11 = 38$. Subtract 11 from both sides to get $9^{x/8} = 27$. Write both sides as powers of 3: $9 = 3^{2}$ and $27 = 3^{3}$, so $(3^{2})^{x/8} = 3^{3}$. Simplify the left side to $3^{2x/8} = 3^{x/4}$. Equating exponents gives $x/4 = 3$, so $x = 12$. This satisfies the original equation because $9^{12/8} = 9^{3/2} = (3^{2})^{3/2} = 3^{3} = 27$, and $27 + 11 = 38$.
**Faster approach:** Rewrite 9 and 27 as powers of 3 immediately and equate exponents: $9^{x/8} = 27$ -> $(3^{2})^{x/8} =$ $3^{3}$ -> $x/4 = 3$ -> $x = 12$.'),
  ('2f2c1cf2-6778-5b4b-9f23-e653408908b7', 1, null, '**Choice B is correct.** The zeros of $f$ are the solutions of $x^{2} - 42x + 80 = 0$. Solve by factoring: find two numbers that multiply to $80$ and add to $-42$, namely $-2$ and $-40$. Thus $x^{2} - 42x + 80 = (x - 2)(x - 40)$, which displays the zeros $x = 2$ and $x = 40$ directly as constants in the factors.
**Choice A is incorrect.** Writing $-42x$ as $-5x - 37x$ is an identity but does not produce factors or show the zeros; it just splits a term.
**Choice C is incorrect.** Writing $f(x) = x(x - 42) + 80$ groups terms but the added $+80$ prevents zeros from being read off as $x = 0$ or $x = 42$; those would be zeros only if the constant were $0$.
**Choice D is incorrect.** Completing the square gives $f(x) = (x - 21)^{2} - 361$, which can be used to find zeros by solving $(x - 21)^{2} = 361$, but the zeros are not presented directly as constants in linear factors the way they are in choice B.
**Faster approach:** Look for factor pairs of $80$ that sum to $42$ (with signs): $2$ and $40$ immediately give $(x -$ $2)(x - 40)$, revealing the zeros.'),
  ('5773e888-fa67-597b-b38f-baa6502d18cd', null, array['49']::text[], '**The correct answer is 49.** The outputs decrease by 3 when x increases by 1, so the slope is $m = -3$. Using the form $g(x) = mx + b$ and the point $(1,46)$ gives $46 = (-3)(1) + b$, so $b = 46 + 3 = 49$.
**Faster approach:** Recognize consecutive outputs differ by a constant $-3$, so $m = -3$, then add $3$ to the value at $x = 1$ (or add $2 \cdot 3$ to value at $x = -1$ if given) to find the $y$-intercept quickly: $46 + 3 = 49$.'),
  ('7f0b607d-ef02-5b5f-9847-6a949537c0a8', 1, null, '**Choice B is correct.** Adding the two equations eliminates $y$: $(x + 5y) + (x - 5y) = 5 + 3$, so $2x = 8$ and $x =$ $4$. Thus the solution has $x = 4$, which matches choice B.
**Choice A is incorrect.** If $x = 0.8$, then substituting into the first equation gives $0.8 + 5y = 5$, so $5y = 4.2$ and $y = 0.84$, which does not satisfy the second equation $x - 5y = 3$ (it would give $0.8 - 4.2 = -3.4$).
**Choice C is incorrect.** If $x = 5$, then $x + 5y = 5$ would force $5y = 0$ and $y = 0$, but $x - 5y$ would be $5$, not $3$, so $x = 5$ is not a solution.
**Choice D is incorrect.** If $x = 8$, the first equation would give $5y = -3$ and $y = -0.6$, but then $x - 5y = 8 -$ $(-3) = 11$, not $3$, so $x = 8$ is incorrect.
**Faster approach:** Add the two equations to eliminate $y$ and solve $2x = 8$ directly; this method always works for systems where the $y$-terms are opposites.'),
  ('56e637a3-84fc-50af-bb0e-ad05baae2662', 2, null, '**Choice C is correct.** In the given right-angled diagram the two acute angles A and C are complementary, so $A + C = 90°$. For complementary angles, the sine of one equals the cosine of the other, so $\sin C = \cos A$. Since $\cos A = 0.55$, $\sin C = 0.55$.
**Choice A is incorrect.** $0.12$ has no relation to $\cos A$ here; it does not equal $\cos A$ or any derived trig value from the complementary relationship.
**Choice B is incorrect.** $0.45$ is simply $1 - 0.55$, which would be unrelated to $\sin C$; complementary-angle identity gives equality, not subtraction.
**Choice D is incorrect.** $0.84$ is approximately $\sqrt{1 - (0.55)^{2}}$, which would be $\sin A$, not $\sin C$, so it is not the correct value for $\sin C$.
**Faster approach:** Recognize that in a right triangle the acute angles are complementary, so immediately use $\sin (90° - θ) = \cos θ$ to set $\sin C = \cos A$ and read off the given value.'),
  ('599900a7-e6d6-5689-9373-5e28bad20c1b', 3, null, '**Choice D is correct.** The conditional probability of sprinkles given vanilla is the number of vanilla orders with sprinkles divided by the total number of vanilla orders. From the table there are $20$ vanilla orders with sprinkles and $30$ vanilla orders without, so the probability is $20/(20 + 30) = 20/50 = 0.40$.
**Choice A is incorrect.** $0.08$ would correspond to $20/250$, which uses an incorrect total (for example the grand total) instead of conditioning on vanilla only.
**Choice B is incorrect.** $0.13$ (about $1/8$) does not match $20/50$; it is not the fraction of vanilla orders that have sprinkles.
**Choice C is incorrect.** $0.25$ equals $1/4$ and would be $20/80$; that denominator is not the total vanilla orders, so it is the wrong conditional denominator.
**Faster approach:** For conditional probability "A given B," use only the B group as the denominator. Here use only vanilla orders: sprinkles count over (sprinkles + no sprinkles for vanilla) = $20/50$.'),
  ('c4b97001-c095-594f-9695-c076f23a7d31', 3, null, '**Choice D is correct.** Rearranging the equation gives $x(r - 7) - 19x = 25 - 3$, so $x(r - 26) = 22$. If $r = 26$ then the equation becomes $0 \cdot x = 22$, which is impossible and yields no solution; thus $r = 26$ cannot produce exactly one solution.
**Choice A is incorrect.** If $r = 3$ then $r - 26 = -23 \ne 0$, so $x = 22/(-23)$ is a single solution.
**Choice B is incorrect.** If $r = 7$ then $r - 26 = -19 \ne 0$, so $x = 22/(-19)$ is a single solution.
**Choice C is incorrect.** If $r = 22$ then $r - 26 = -4 \ne 0$, so $x = 22/(-4) = -11/2$ is a single solution.
**Faster approach:** Collect x-terms to get $x(r - 26) = 22$. Any $r \ne 26$ gives a nonzero coefficient and thus exactly one solution; $r = 26$ gives $0 = 22$, so no solution.'),
  ('6ec80564-288c-5a86-857f-46b4a767a464', null, array['217']::text[], '**The correct answer is 217.** Start with the $2000$ people who attended the first webinar. Those who also attended the second webinar are $65%$ of $2000$, which is $0.65 \times 2000 = 1300$. Therefore the number who attended the first but not the second is $2000 - 1300 = 700$. Of those $700$, $31%$ attended the third webinar, which is $0.31 \times 700 = 217$ people who attended both the first and third webinars but not the second.
**Faster approach:** Compute successive parts directly: first find first-but-not-second as $2000(1 - 0.65) =$ $2000 \times 0.35 = 700$, then multiply by $0.31$ to get $700 \times 0.31 = 217$. This two-step multiplication avoids unnecessary intermediate counts.'),
  ('85da7257-2a94-5247-a95a-5c7da1ea6d08', 3, null, '**Choice D is correct.** The given circle M has center at $(-6a, 38a)$ and radius $6a$ (since $(x + 6a)^{2} + (y -$ $38a)^{2} = 36a^{2}$). Shifting the circle $12a$ units to the right increases the $x$-coordinate of the center by $12a$, giving the new center $(-6a + 12a, 38a) = (6a, 38a)$. The equation for a circle with center $(6a, 38a)$ and radius $6a$ is $(x - 6a)^{2} + (y - 38a)^{2} = 36a^{2}$, which is Choice D.
**Choice A is incorrect.** Its center would be $(-18a, 38a)$, which results from shifting left by $12a$, not right.
**Choice B is incorrect.** That moves the center vertically to $(-6a, 50a)$ (up $12a$), but the problem specifies a horizontal shift.
**Choice C is incorrect.** That moves the center vertically to $(-6a, 26a)$ (down $12a$), again not the required horizontal shift.
**Faster approach:** For a rightward shift of $12a$, substitute $x ↦ x - 12a$ into the original equation: $(x - 12a +$ $6a)^{2} + (y - 38a)^{2} = (x - 6a)^{2} + (y - 38a)^{2} = 36a^{2}$, immediately giving Choice D.'),
  ('d97e4baa-ed8f-57e2-8150-04cebf009d38', 2, null, '**Choice C is correct.** Adding the same number (14) to every data value increases the mean by 14 and does not change the range. From the dot plot the mean capacity of set A is 10 μF (the distribution is centered at 10), so the mean for set B is $10 + 14 = 24$ μF. The minimum and maximum capacities in set A are 4 μF and 16 μF, so the range is $16 - 4 = 12$ μF; adding 14 to every value leaves the range $12$ μF.
**Choice A is incorrect.** Although it gives the range 12 μF, it lists the mean as 10 μF; the mean of set B must be 14 greater than set A’s mean, so 10 μF is the mean of set A, not set B.
**Choice B is incorrect.** It gives the mean for set B as 10 μF (wrong for the same reason as A) and also an incorrect range of 26 μF; the range does not change when every value is increased by the same amount.
**Choice D is incorrect.** While it gives the mean 24 μF correctly, it lists the range as 26 μF, which is wrong because adding a constant to every observation does not change the range (the range remains 12 μF).
**Faster approach:** Recognize that adding a constant to every data value increases the mean by that constant and leaves the range unchanged; use the original mean and min/max to get the new mean and range.')
